insert into didactic_payload values ($didactic_1d23a6e242e5c256${"version":1,"reviewed_at":"2026-10-24T22:00:40.123042+00:00","actor":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","topic":{"id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","block_name":"Histórico 2026","created_at":"2026-09-28T03:22:06.477804+00:00","discipline":"Direito Constitucional","edition_id":"c0ea9fc5-d65d-4f8c-a936-729f8824a072","topic_text":"DIREITO CONSTITUCIONAL (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Teoria da Constituição. 1.1. Conceito, Objeto e Classificações das Constituições. 1.2. Poder Constituinte: Titularidade, espécies (originário, derivado, decorrente, difuso), características e limites do poder constituinte originário. 1.3. Mutação Constitucional e Reforma Constitucional: Emendas e Revisão. 1.4. Supremacia da Constituição e o Bloco de Constitucionalidade. 1.5. Normas Constitucionais: Classificação quanto à eficácia e aplicabilidade (normas de eficácia plena, contida e limitada). 2. Controle de Constitucionalidade. 2.1. Conceito e Histórico. 2.2. Sistemas de Controle de Constitucionalidade: Difuso e Concentrado. 2.3. Ação Direta de Inconstitucionalidade (ADI). 2.4. Ação Declaratória de Constitucionalidade (ADC). 2.5. Arguição de Descumprimento de Preceito Fundamental (ADPF). 2.6. Ação Direta de Inconstitucionalidade por Omissão (ADO). 2.7. Recurso Extraordinário. 2.8. Efeitos das decisões em controle de constitucionalidade. 3. Direitos e Garantias Fundamentais. 3.1. Direitos e Deveres Individuais e Coletivos (art. 5º da CF). 3.2. Direitos Sociais (arts. 6º a 11 da CF). 3.3. Nacionalidade (arts. 12 e 13 da CF). 3.4. Direitos Políticos (arts. 14 a 16 da CF). 3.5. Partidos Políticos (art. 17 da CF). 4. Organização do Estado. 4.1. Organização Político-Administrativa da República Federativa do Brasil (arts. 18 e 19 da CF). 4.2. Repartição de Competências. 4.3. Intervenção Federal (arts. 34 a 36 da CF). 4.4. Administração Pública (arts. 37 a 41 da CF). 5. Organização dos Poderes. 5.1. Poder Legislativo (arts. 44 a 70 da CF). 5.2. Poder Executivo (arts. 76 a 91 da CF). 5.3. Poder Judiciário (arts. 92 a 126 da CF). 5.4. Funções Essenciais à Justiça (arts. 127 a 135 da CF). 6. Defesa do Estado e das Instituições Democráticas. 6.1. Estado de Defesa (arts. 136 e 137 da CF). 6.2. Estado de Sítio (arts. 138 e 139 da CF). 6.3. Forças Armadas (arts. 142 e 143 da CF). 7. Segurança Pública. 7.1. Disposições Gerais (art. 144 da CF). 7.2. Órgãos de Segurança Pública. 7.3. Atribuições da Polícia Civil. 8. Ordem Social. 8.1. Base e Objetivos da Ordem Social. 8.2. Seguridade Social (arts. 194 a 204 da CF). 8.3. Educação, Cultura e Desporto (arts. 205 a 217 da CF). 8.4. Meio Ambiente (art. 225 da CF). 8.5. Família, Criança, Adolescente, Jovem e Idoso (arts. 226 a 230 da CF). 9. Constituição do Estado do Piauí. 9.1. Princípios Fundamentais do Estado do Piauí. 9.2. Direitos e Garantias Fundamentais no âmbito estadual. 9.3. Organização dos Poderes Estaduais. 9.4. Administração Pública Estadual. 9.5. Segurança Pública Estadual.","topic_order":2,"content_status":"current"},"edition":{"id":"c0ea9fc5-d65d-4f8c-a936-729f8824a072","status":"active","role_name":"Delegado de Polícia Civil","source_id":"6d246b75-f48d-5433-804e-8c2999e120bb","created_at":"2026-09-28T03:22:03.801841+00:00","exam_board":"FGV","contest_name":"Polícia Civil do Piauí","contest_year":2026},"sources":[{"id":"31420f66-9c12-4787-bdc0-f55f77525880","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","notes":"Conferência limitada aos dispositivos utilizados no módulo de princípios fundamentais; não certifica auditoria integral do diploma. SHA-256 do documento consultado: 82a054357e7b18f0a2f1d2c1d584a1ef77ff40842cf7297d9ff9fc78f9929349","title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","issuer":"Presidência da República — Planalto","status":"vigente","checked_at":"2026-10-24T20:38:35.690514+00:00","is_official":true,"source_type":"constituicao","published_on":null},{"id":"08b768e4-0a5f-436f-877c-5d1de1035a60","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","notes":"Dispositivos citados conferidos na revisão individual. Esta conferência não certifica a íntegra de toda a norma.\nConsulta oficial da Súmula Vinculante 25 e dos precedentes reproduzidos nesta página em 24/10/2026. Confirmação limitada à vedação de prisão civil de depositário infiel e ao recorte de tratados de direitos humanos empregado no lote; não certifica toda jurisprudência. SHA-256: bc86006e17122d1adbcb84afabff011071c4d7aa66f1fdfb642aa303fefe8861. SV25-constitucional-continuacao-20261024","title":"STF — Súmula Vinculante 25","issuer":"Supremo Tribunal Federal","status":"vigente","checked_at":"2026-10-24T20:54:31.843369+00:00","is_official":true,"source_type":"jurisprudencia","published_on":null}],"counts":{"published":164,"needs_review":25,"duplicate_reused":3},"rows":[{"input_index":0,"statement":"A democracia brasileira é exclusivamente indireta ou representativa, sem nenhuma forma constitucional de exercício direto do poder pelo povo.","content_fingerprint":"a democracia brasileira e exclusivamente indireta ou representativa sem nenhuma forma constitucional de exercicio direto do poder pelo povo","audit":{"id":"5b8496be-e13f-544d-a04d-7c468c1c50b5","document_sha256":"3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9","document_name":"01-02_AlfaCon--principios-fundamentais-parte-2.pdf","source_page":3,"item_number":1,"extracted_statement":"A democracia brasileira é indireta, ou representativa, haja vista que o poder popular se expressa por meio de representantes eleitos, que recebem mandato para a elaboração das leis e a fiscalização dos atos estatais.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático. Redação delimitada/atualizada para evitar ambiguidade ou regra superada.","question_table":"curated_question_catalog","question_id":"9c00071b-e449-5199-8464-c7d2ff897f55","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"9c00071b-e449-5199-8464-c7d2ff897f55","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Princípios fundamentais","tested_topic":"Princípios fundamentais","question_text":"A democracia brasileira é exclusivamente indireta ou representativa, sem nenhuma forma constitucional de exercício direto do poder pelo povo.","official_answer":"E","explanation":"O enunciado reduz a democracia à representação. A Constituição admite exercício do poder por representantes eleitos ou diretamente, nos seus termos. Base conferida: Art. 1º, parágrafo único. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 1º, parágrafo único"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"01-02_AlfaCon--principios-fundamentais-parte-2.pdf","documentTitle":"Principios fundamentais parte 2","publisher":"AlfaCon","documentSha256":"3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9","page":3,"itemNumber":1,"materialSlug":"constitucional-principios-fundamentais-federacao-republica","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":1,"statement":"O estabelecimento pela CF de que todo o poder emana do povo, que o exerce por meio de representantes eleitos ou diretamente, nos seus termos, evidencia a adoção da democracia semidireta ou participativa.","content_fingerprint":"o estabelecimento pela cf de que todo o poder emana do povo que o exerce por meio de representantes eleitos ou diretamente nos seus termos evidencia a adocao da democracia semidireta ou participativa","audit":{"id":"9b4df3b0-04c6-5063-a7a4-cb4f65fec0e6","document_sha256":"3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9","document_name":"01-02_AlfaCon--principios-fundamentais-parte-2.pdf","source_page":3,"item_number":2,"extracted_statement":"O estabelecimento pela CF de que todo o poder emana do povo, que o exerce por meio de representantes eleitos ou diretamente, nos seus termos, evidencia a adoção da democracia semidireta ou participativa.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"5e75589d-1510-5760-9211-1633051fd36c","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"5e75589d-1510-5760-9211-1633051fd36c","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9:2","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Princípios fundamentais","tested_topic":"Princípios fundamentais","question_text":"O estabelecimento pela CF de que todo o poder emana do povo, que o exerce por meio de representantes eleitos ou diretamente, nos seus termos, evidencia a adoção da democracia semidireta ou participativa.","official_answer":"C","explanation":"A combinação de representação e participação direta corresponde ao texto constitucional. Exemplo: eleições de representantes não afastam os instrumentos constitucionais de participação popular. Base conferida: Art. 1º, parágrafo único. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 1º, parágrafo único"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"01-02_AlfaCon--principios-fundamentais-parte-2.pdf","documentTitle":"Principios fundamentais parte 2","publisher":"AlfaCon","documentSha256":"3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9","page":3,"itemNumber":2,"materialSlug":"constitucional-principios-fundamentais-federacao-republica","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":2,"statement":"O regime político adotado na CF caracteriza a República Federativa do Brasil como um Estado democrático de direito em que se conjuga o princípio representativo com a participação direta do povo por meio do voto, do plebiscito, do referendo e da iniciativa popular.","content_fingerprint":"o regime politico adotado na cf caracteriza a republica federativa do brasil como um estado democratico de direito em que se conjuga o principio representativo com a participacao direta do povo por meio do voto do plebiscito do referendo e da iniciativa popular","audit":{"id":"3428957b-8ec8-5880-93d2-e57e2e78fe45","document_sha256":"3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9","document_name":"01-02_AlfaCon--principios-fundamentais-parte-2.pdf","source_page":3,"item_number":3,"extracted_statement":"O regime político adotado na CF caracteriza a República Federativa do Brasil como um Estado democrático de direito em que se conjuga o princípio representativo com a participação direta do povo por meio do voto, do plebiscito, do referendo e da iniciativa popular.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"e30b316d-703b-56da-abdb-857a32d50128","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"e30b316d-703b-56da-abdb-857a32d50128","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Princípios fundamentais","tested_topic":"Princípios fundamentais","question_text":"O regime político adotado na CF caracteriza a República Federativa do Brasil como um Estado democrático de direito em que se conjuga o princípio representativo com a participação direta do povo por meio do voto, do plebiscito, do referendo e da iniciativa popular.","official_answer":"C","explanation":"A Constituição combina representação com os instrumentos de participação previstos. A classificação didática não dispensa os requisitos de cada instrumento. Base conferida: Art. 1º, parágrafo único; Art. 14. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 1º, parágrafo único; Art. 14"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"01-02_AlfaCon--principios-fundamentais-parte-2.pdf","documentTitle":"Principios fundamentais parte 2","publisher":"AlfaCon","documentSha256":"3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9","page":3,"itemNumber":3,"materialSlug":"constitucional-principios-fundamentais-federacao-republica","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":3,"statement":"O princípio democrático é pertinente aos regimes políticos, evidenciado pela titularidade do poder estatal pelos cidadãos e exercido por meio da representação política, com o fim de atender aos interesses populares","content_fingerprint":"o principio democratico e pertinente aos regimes politicos evidenciado pela titularidade do poder estatal pelos cidadaos e exercido por meio da representacao politica com o fim de atender aos interesses populares","audit":{"id":"c2ed7704-5446-5fc1-b495-53c7e22f2bc6","document_sha256":"3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9","document_name":"01-02_AlfaCon--principios-fundamentais-parte-2.pdf","source_page":3,"item_number":4,"extracted_statement":"O princípio democrático é pertinente aos regimes políticos, evidenciado pela titularidade do poder estatal pelos cidadãos e exercido por meio da representação política, com o fim de atender aos interesses populares","provided_answer":"CERTO","current_answer":null,"review_status":"needs_review","review_note":"Delimitar titularidade do poder e exercício democrático; o enunciado mistura povo e cidadãos.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":4,"statement":"Entre os princípios fundamentais da República Federativa do Brasil inclui-se o princípio democrático, que se refere ao exercício direto e indireto do poder pelo povo.","content_fingerprint":"entre os principios fundamentais da republica federativa do brasil inclui se o principio democratico que se refere ao exercicio direto e indireto do poder pelo povo","audit":{"id":"b60c67be-4da2-5b86-a1bc-3413b978fee8","document_sha256":"3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9","document_name":"01-02_AlfaCon--principios-fundamentais-parte-2.pdf","source_page":3,"item_number":5,"extracted_statement":"Entre os princípios fundamentais da República Federativa do Brasil inclui-se o princípio democrático, que se refere ao exercício direto e indireto do poder pelo povo.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"03a763ac-0d7b-53bd-8f6c-3196faa9092a","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"03a763ac-0d7b-53bd-8f6c-3196faa9092a","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9:5","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Princípios fundamentais","tested_topic":"Princípios fundamentais","question_text":"Entre os princípios fundamentais da República Federativa do Brasil inclui-se o princípio democrático, que se refere ao exercício direto e indireto do poder pelo povo.","official_answer":"C","explanation":"O princípio democrático relaciona-se à origem popular do poder e às formas constitucionais de seu exercício, sem limitar-se a uma única via. Base conferida: Art. 1º, parágrafo único. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 1º, parágrafo único"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"01-02_AlfaCon--principios-fundamentais-parte-2.pdf","documentTitle":"Principios fundamentais parte 2","publisher":"AlfaCon","documentSha256":"3e69fdfb170dd1669eb4d80cde33151a43b734f38ea31d1967a3086cb11f2ac9","page":3,"itemNumber":5,"materialSlug":"constitucional-principios-fundamentais-federacao-republica","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":5,"statement":"A dignidade da pessoa humana, princípio fundamental da República Federativa do Brasil, promove o direito à vida digna em sociedade, em prol do bem comum, fazendo prevalecer o interesse coletivo em detrimento do direito individual.","content_fingerprint":"a dignidade da pessoa humana principio fundamental da republica federativa do brasil promove o direito a vida digna em sociedade em prol do bem comum fazendo prevalecer o interesse coletivo em detrimento do direito individual","audit":{"id":"b44c3305-ee7f-51dd-8f10-695234f931c5","document_sha256":"76c15d66dfd0e0c8359ee2e7cf7f1765ec012724776be6afce7a56d5c1ced5e4","document_name":"01-03_AlfaCon--principios-fundamentais-parte-3.pdf","source_page":3,"item_number":1,"extracted_statement":"A dignidade da pessoa humana, princípio fundamental da República Federativa do Brasil, promove o direito à vida digna em sociedade, em prol do bem comum, fazendo prevalecer o interesse coletivo em detrimento do direito individual.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"b71a5be9-22bb-5e43-80f8-e9d1068c89a4","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"b71a5be9-22bb-5e43-80f8-e9d1068c89a4","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:76c15d66dfd0e0c8359ee2e7cf7f1765ec012724776be6afce7a56d5c1ced5e4:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Princípios fundamentais","tested_topic":"Princípios fundamentais","question_text":"A dignidade da pessoa humana, princípio fundamental da República Federativa do Brasil, promove o direito à vida digna em sociedade, em prol do bem comum, fazendo prevalecer o interesse coletivo em detrimento do direito individual.","official_answer":"E","explanation":"Dignidade não estabelece prevalência automática de todo interesse coletivo sobre qualquer direito individual. É necessário interpretar as garantias e o caso concreto. Base conferida: Art. 1º, III; Art. 5º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 1º, III; Art. 5º"}],"difficulty":"média","con