10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"9b3582c1-2959-5421-b87c-0747a64ac34f","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:76c15d66dfd0e0c8359ee2e7cf7f1765ec012724776be6afce7a56d5c1ced5e4:6","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Princípios fundamentais","tested_topic":"Princípios fundamentais","question_text":"Os valores sociais do trabalho e da livre iniciativa impedem a intervenção do Estado na ordem econômica.","official_answer":"E","explanation":"A livre iniciativa convive com a ordem econômica constitucional e suas condições. O fundamento não proíbe toda intervenção estatal, independentemente de finalidade e competência. Base conferida: Art. 1º, IV; Art. 170. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 1º, IV; Art. 170"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"01-03_AlfaCon--principios-fundamentais-parte-3.pdf","documentTitle":"Principios fundamentais parte 3","publisher":"AlfaCon","documentSha256":"76c15d66dfd0e0c8359ee2e7cf7f1765ec012724776be6afce7a56d5c1ced5e4","page":4,"itemNumber":6,"materialSlug":"constitucional-principios-fundamentais-federacao-republica","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":11,"statement":"O pluralismo político é princípio fundamental que assegura aos cidadãos até mesmo o apartidarismo.","content_fingerprint":"o pluralismo politico e principio fundamental que assegura aos cidadaos ate mesmo o apartidarismo","audit":{"id":"2b5026af-017f-5bba-92b4-24358331be40","document_sha256":"76c15d66dfd0e0c8359ee2e7cf7f1765ec012724776be6afce7a56d5c1ced5e4","document_name":"01-03_AlfaCon--principios-fundamentais-parte-3.pdf","source_page":4,"item_number":7,"extracted_statement":"O pluralismo político é princípio fundamental que assegura aos cidadãos até mesmo o apartidarismo.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"7dcf0d19-cf96-56c4-bbad-e797cd6cbcd0","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"7dcf0d19-cf96-56c4-bbad-e797cd6cbcd0","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:76c15d66dfd0e0c8359ee2e7cf7f1765ec012724776be6afce7a56d5c1ced5e4:7","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Princípios fundamentais","tested_topic":"Princípios fundamentais","question_text":"O pluralismo político é princípio fundamental que assegura aos cidadãos até mesmo o apartidarismo.","official_answer":"C","explanation":"A proteção ao pluralismo não impõe filiação partidária a todo cidadão. Deve-se distinguir diversidade política de obrigação de integrar um partido. Base conferida: Art. 1º, V; Art. 5º, XX. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 1º, V; Art. 5º, XX"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"01-03_AlfaCon--principios-fundamentais-parte-3.pdf","documentTitle":"Principios fundamentais parte 3","publisher":"AlfaCon","documentSha256":"76c15d66dfd0e0c8359ee2e7cf7f1765ec012724776be6afce7a56d5c1ced5e4","page":4,"itemNumber":7,"materialSlug":"constitucional-principios-fundamentais-federacao-republica","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":12,"statement":"A concessão de asilo político a estrangeiro é princípio que rege a República Federativa do Brasil nas suas relações internacionais, mas, como ato de soberania estatal, o Estado brasileiro não está obrigado a realizá-lo.","content_fingerprint":"a concessao de asilo politico a estrangeiro e principio que rege a republica federativa do brasil nas suas relacoes internacionais mas como ato de soberania estatal o estado brasileiro nao esta obrigado a realiza lo","audit":{"id":"b40985d9-b682-568e-826a-4519488b309b","document_sha256":"76c15d66dfd0e0c8359ee2e7cf7f1765ec012724776be6afce7a56d5c1ced5e4","document_name":"01-03_AlfaCon--principios-fundamentais-parte-3.pdf","source_page":4,"item_number":8,"extracted_statement":"A concessão de asilo político a estrangeiro é princípio que rege a República Federativa do Brasil nas suas relações internacionais, mas, como ato de soberania estatal, o Estado brasileiro não está obrigado a realizá-lo.","provided_answer":"CERTO","current_answer":null,"review_status":"needs_review","review_note":"Exige conferir a disciplina atual de asilo e os limites de discricionariedade em fonte oficial pertinente.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":13,"statement":"A livre iniciativa, fundamento da República Federativa do Brasil, possui valor social que transcende o interesse do empreendedor, merecendo proteção constitucional apenas quando respeitar e ajudar a desenvolver o trabalho humano. Por isso, não se coaduna com a CF empreitada que deixe de assegurar os direitos sociais dos trabalhadores.","content_fingerprint":"a livre iniciativa fundamento da republica federativa do brasil possui valor social que transcende o interesse do empreendedor merecendo protecao constitucional apenas quando respeitar e ajudar a desenvolver o trabalho humano por isso nao se coaduna com a cf empreitada que deixe de assegurar os direitos sociais dos trabalhadores","audit":{"id":"96345344-92d8-556b-9b67-263befac249b","document_sha256":"76c15d66dfd0e0c8359ee2e7cf7f1765ec012724776be6afce7a56d5c1ced5e4","document_name":"01-03_AlfaCon--principios-fundamentais-parte-3.pdf","source_page":4,"item_number":9,"extracted_statement":"A livre iniciativa, fundamento da República Federativa do Brasil, possui valor social que transcende o interesse do empreendedor, merecendo proteção constitucional apenas quando respeitar e ajudar a desenvolver o trabalho humano. Por isso, não se coaduna com a CF empreitada que deixe de assegurar os direitos sociais dos trabalhadores.","provided_answer":"CERTO","current_answer":null,"review_status":"needs_review","review_note":"Enunciado excessivamente aberto sobre condicionamento da livre iniciativa; delimitar e conferir o fundamento.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":14,"statement":"O pluralismo político, fundamento da República Federativa do Brasil, é pautado pela tolerância a ideologias diversas, o que exclui discursos de ódio, não amparados pela liberdade de manifestação do pensamento.","content_fingerprint":"o pluralismo politico fundamento da republica federativa do brasil e pautado pela tolerancia a ideologias diversas o que exclui discursos de odio nao amparados pela liberdade de manifestacao do pensamento","audit":{"id":"a89bcbf7-63b1-5610-8357-099c6d56e098","document_sha256":"76c15d66dfd0e0c8359ee2e7cf7f1765ec012724776be6afce7a56d5c1ced5e4","document_name":"01-03_AlfaCon--principios-fundamentais-parte-3.pdf","source_page":4,"item_number":10,"extracted_statement":"O pluralismo político, fundamento da República Federativa do Brasil, é pautado pela tolerância a ideologias diversas, o que exclui discursos de ódio, não amparados pela liberdade de manifestação do pensamento.","provided_answer":"CERTO","current_answer":null,"review_status":"needs_review","review_note":"Exige fonte jurisprudencial atual sobre limites da expressão e discurso de ódio.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":15,"statement":"Direito fundamental pode sofrer limitações, mas é inadmissível que se atinja seu núcleo essencial de forma tal que se lhe desnature a essência.","content_fingerprint":"direito fundamental pode sofrer limitacoes mas e inadmissivel que se atinja seu nucleo essencial de forma tal que se lhe desnature a essencia","audit":{"id":"3af49a56-8cd9-5c71-8d32-0f5e806d1148","document_sha256":"be4d4890315c3384ed62adceaa6b388a54c501985dea13edb5aab16b9c74018c","document_name":"02-01_AlfaCon--direitos-fundamentais-teoria-geral-parte-1.pdf","source_page":4,"item_number":1,"extracted_statement":"Direito fundamental pode sofrer limitações, mas é inadmissível que se atinja seu núcleo essencial de forma tal que se lhe desnature a essência.","provided_answer":"CERTO","current_answer":null,"review_status":"needs_review","review_note":"Delimitar alcance de núcleo essencial sem generalizar regime de toda restrição.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":16,"statement":"Na CF, a classificação dos direitos e garantias fundamentais restringe-se a três categorias: os direitos individuais e coletivos, os direitos de nacionalidade e os direitos políticos.","content_fingerprint":"na cf a classificacao dos direitos e garantias fundamentais restringe se a tres categorias os direitos individuais e coletivos os direitos de nacionalidade e os direitos politicos","audit":{"id":"60ab1e3f-d25b-5ad4-9652-04496240e0de","document_sha256":"be4d4890315c3384ed62adceaa6b388a54c501985dea13edb5aab16b9c74018c","document_name":"02-01_AlfaCon--direitos-fundamentais-teoria-geral-parte-1.pdf","source_page":4,"item_number":2,"extracted_statement":"Na CF, a classificação dos direitos e garantias fundamentais restringe-se a três categorias: os direitos individuais e coletivos, os direitos de nacionalidade e os direitos políticos.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"e7c849f1-5334-508c-9121-37345f8b2874","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"e7c849f1-5334-508c-9121-37345f8b2874","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:be4d4890315c3384ed62adceaa6b388a54c501985dea13edb5aab16b9c74018c:2","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Teoria geral dos direitos fundamentais","tested_topic":"Teoria geral dos direitos fundamentais","question_text":"Na CF, a classificação dos direitos e garantias fundamentais restringe-se a três categorias: os direitos individuais e coletivos, os direitos de nacionalidade e os direitos políticos.","official_answer":"E","explanation":"O Título II também abrange direitos sociais e partidos políticos. A enumeração de apenas três categorias está incompleta. Base conferida: Arts. 5º a 17. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Arts. 5º a 17"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-01_AlfaCon--direitos-fundamentais-teoria-geral-parte-1.pdf","documentTitle":"Direitos fundamentais teoria geral parte 1","publisher":"AlfaCon","documentSha256":"be4d4890315c3384ed62adceaa6b388a54c501985dea13edb5aab16b9c74018c","page":4,"itemNumber":2,"materialSlug":"constitucional-direitos-fundamentais-teoria-geral","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":17,"statement":"Os tratados de direitos humanos, ainda que aprovados apenas no Senado Federal, em dois turnos e por maioria qualificada, equiparam-se às emendas constitucionais.","content_fingerprint":"os tratados de direitos humanos ainda que aprovados apenas no senado federal em dois turnos e por maioria qualificada equiparam se as emendas constitucionais","audit":{"id":"6798a99b-7700-55af-86ac-8a53b3483037","document_sha256":"10dd852a63816c83b9ecbc0a5349fdcb5eadf65bd19f6d845e35c99c2d94b679","document_name":"02-02_AlfaCon--direitos-fundamentais-teoria-geral-parte-2.pdf","source_page":6,"item_number":1,"extracted_statement":"Os tratados de direitos humanos, ainda que aprovados apenas no Senado Federal, em dois turnos e por maioria qualificada, equiparam-se às emendas constitucionais.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"170b1b9f-94eb-5911-bb69-69a3fe188ce1","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"170b1b9f-94eb-5911-bb69-69a3fe188ce1","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:10dd852a63816c83b9ecbc0a5349fdcb5eadf65bd19f6d845e35c99c2d94b679:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Teoria geral dos direitos fundamentais","tested_topic":"Teoria geral dos direitos fundamentais","question_text":"Os tratados de direitos humanos, ainda que aprovados apenas no Senado Federal, em dois turnos e por maioria qualificada, equiparam-se às emendas constitucionais.","official_answer":"E","explanation":"O rito exige votação em cada Casa do Congresso, em dois turnos, por três quintos dos respectivos membros. Aprovação apenas no Senado não basta. Base conferida: Art. 5º, § 3º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 5º, § 3º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-02_AlfaCon--direitos-fundamentais-teoria-geral-parte-2.pdf","documentTitle":"Direitos fundamentais teoria geral parte 2","publisher":"AlfaCon","documentSha256":"10dd852a63816c83b9ecbc0a5349fdcb5eadf65bd19f6d845e35c99c2d94b679","page":6,"itemNumber":1,"materialSlug":"constitucional-direitos-fundamentais-teoria-geral","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":18,"statement":"Como regra, os direitos e garantias fundamentais se estabelecem na relação entre o particular e o Poder Público; porém, pela teoria da eficácia vertical dos direitos fundamentais e garantias fundamentais, ocorre a aplicação das ditas liberdades públicas também no plano das relações travadas exclusivamente entre particulares.","content_fingerprint":"como regra os direitos e garantias fundamentais se estabelecem na relacao entre o particular e o poder publico porem pela teoria da eficacia vertical dos direitos fundamentais e garantias fundamentais ocorre a aplicacao das ditas liberdades publicas tambem no plano das relacoes travadas exclusivamente entre particulares","audit":{"id":"18a69d7c-04f4-59bb-8415-18ebbeca7402","document_sha256":"10dd852a63816c83b9ecbc0a5349fdcb5eadf65bd19f6d845e35c99c2d94b679","document_name":"02-02_AlfaCon--direitos-fundamentais-teoria-geral-parte-2.pdf","source_page":7,"item_number":2,"extracted_statement":"Como regra, os direitos e garantias fundamentais se estabelecem na relação entre o particular e o Poder Público; porém, pela teoria da eficácia vertical dos direitos fundamentais e garantias fundamentais, ocorre a aplicação das ditas liberdades públicas também no plano das relações travadas exclusivamente entre particulares.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"e3378367-f57f-506f-99a4-ed7268f8e2c0","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"e3378367-f57f-506f-99a4-ed7268f8e2c0","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:10dd852a63816c83b9ecbc0a5349fdcb5eadf65bd19f6d845e35c99c2d94b679:2","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Teoria geral dos direitos fundamentais","tested_topic":"Teoria geral dos direitos fundamentais","question_text":"Como regra, os direitos e garantias fundamentais se estabelecem na relação entre o particular e o Poder Público; porém, pela teoria da eficácia vertical dos direitos fundamentais e garantias fundamentais, ocorre a aplicação das ditas liberdades públicas também no plano das relações travadas exclusivamente entre particulares.","official_answer":"E","explanation":"Na terminologia didática, a eficácia vertical se refere à relação com o Estado; horizontal se refere às relações privadas. O item trocou a denominação, sem que isso resolva automaticamente todo caso concreto. Base conferida: Art. 5º, § 1º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 5º, § 1º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-02_AlfaCon--direitos-fundamentais-teoria-geral-parte-2.pdf","documentTitle":"Direitos fundamentais teoria geral parte 2","publisher":"AlfaCon","documentSha256":"10dd852a63816c83b9ecbc0a5349fdcb5eadf65bd19f6d845e35c99c2d94b679","page":7,"itemNumber":2,"materialSlug":"constitucional-direitos-fundamentais-teoria-geral","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":19,"statement":"Em regra, as normas constitucionais que prescrevem direitos fundamentais têm eficácia contida e dependem de regulamentação.","content_fingerprint":"em regra as normas constitucionais que prescrevem direitos fundamentais tem eficacia contida e dependem de regulamentacao","audit":{"id":"3ec0f602-9579-5a97-99d1-76f9bafafb8a","document_sha256":"10dd852a63816c83b9ecbc0a5349fdcb5eadf65bd19f6d845e35c99c2d94b679","document_name":"02-02_AlfaCon--direitos-fundamentais-teoria-geral-parte-2.pdf","source_page":7,"item_number":3,"extracted_statement":"Em regra, as normas constitucionais que prescrevem direitos fundamentais têm eficácia contida e dependem de regulamentação.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"1b788a97-c853-5ff0-821d-6fda9ab7ca24","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"1b788a97-c853-5ff0-821d-6fda9ab7ca24","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:10dd852a63816c83b9ecbc0a5349fdcb5eadf65bd19f6d845e35c99c2d94b679:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Teoria geral dos direitos fundamentais","tested_topic":"Teoria geral dos direitos fundamentais","question_text":"Em regra, as normas constitucionais que prescrevem direitos fundamentais têm eficácia contida e dependem de regulamentação.","official_answer":"E","explanation":"A aplicação imediata não permite classificar todos os direitos, em regra, como dependentes de regulamentação. É necessário identificar a norma e os efeitos discutidos. Base conferida: Art. 5º, § 1º; Art. 5º, LXXI. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 5º, § 1º; Art. 5º, LXXI"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-02_AlfaCon--direitos-fundamentais-teoria-geral-parte-2.pdf","documentTitle":"Direitos fundamentais teoria geral parte 2","publisher":"AlfaCon","documentSha256":"10dd852a63816c83b9ecbc0a5349fdcb5eadf65bd19f6d845e35c99c2d94b679","page":7,"itemNumber":3,"materialSlug":"constitucional-direitos-fundamentais-teoria-geral","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":20,"statement":"O Brasil se submeterá à jurisdição de Tribunal Penal Internacional a cuja criação manifestar adesão.","content_fingerprint":"o brasil se submetera a jurisdicao de tribunal penal internacional a cuja criacao manifestar adesao","audit":{"id":"f5a64f7d-8c50-5b9f-a3bd-f6a03e610f5b","document_sha256":"10dd852a63816c83b9ecbc0a5349fdcb5eadf65bd19f6d845e35c99c2d94b679","document_name":"02-02_AlfaCon--direitos-fundamentais-teoria-geral-parte-2.pdf","source_page":7,"item_number":4,"extracted_statement":"O Brasil se submeterá à jurisdição de Tribunal Penal Internacional a cuja criação manifestar adesão.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"16bb40a2-ceab-5142-a247-c39d05d21453","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0