745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb","document_name":"05-03_AlfaCon--organizacao-do-estado.pdf","source_page":5,"item_number":9,"extracted_statement":"A forma federativa de Estado, caracterizada pela divisão territorial do poder, foi gravada na CF como cláusula pétrea.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"c11314b8-7e36-51d2-a4e0-079b0ebacb02","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"c11314b8-7e36-51d2-a4e0-079b0ebacb02","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb:9","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Organização do Estado","tested_topic":"Organização do Estado","question_text":"A forma federativa de Estado, caracterizada pela divisão territorial do poder, foi gravada na CF como cláusula pétrea.","official_answer":"C","explanation":"A proteção impede deliberar proposta tendente a abolir a forma federativa. Não significa congelar toda regra de competência sem exame do conteúdo da reforma. Base conferida: Art. 60, § 4º, I. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 60, § 4º, I"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"05-03_AlfaCon--organizacao-do-estado.pdf","documentTitle":"Organizacao do estado","publisher":"AlfaCon","documentSha256":"7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb","page":5,"itemNumber":9,"materialSlug":"constitucional-organizacao-estado-competencias","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":127,"statement":"Os Territórios federais não se configuram como entes federativos, alçados que estão à categoria de autarquia territorial da União, de modo que, caso um Território federal venha a ser criado, esse não terá Poder Legislativo próprio nem disporá de representação na Câmara dos Deputados ou no Senado Federal.","content_fingerprint":"os territorios federais nao se configuram como entes federativos alcados que estao a categoria de autarquia territorial da uniao de modo que caso um territorio federal venha a ser criado esse nao tera poder legislativo proprio nem dispora de representacao na camara dos deputados ou no senado federal","audit":{"id":"c99a6b1a-5cc3-5cb9-be1a-6b18ad2435e5","document_sha256":"7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb","document_name":"05-03_AlfaCon--organizacao-do-estado.pdf","source_page":5,"item_number":10,"extracted_statement":"Os Territórios federais não se configuram como entes federativos, alçados que estão à categoria de autarquia territorial da União, de modo que, caso um Território federal venha a ser criado, esse não terá Poder Legislativo próprio nem disporá de representação na Câmara dos Deputados ou no Senado Federal.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"3e78a066-4df4-5262-9f37-f7488f6b20b4","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"3e78a066-4df4-5262-9f37-f7488f6b20b4","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb:10","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Organização do Estado","tested_topic":"Organização do Estado","question_text":"Os Territórios federais não se configuram como entes federativos, alçados que estão à categoria de autarquia territorial da União, de modo que, caso um Território federal venha a ser criado, esse não terá Poder Legislativo próprio nem disporá de representação na Câmara dos Deputados ou no Senado Federal.","official_answer":"E","explanation":"A ausência de condição federativa autônoma não permite negar toda representação e organização territorial. A Constituição prevê quatro deputados por território e disciplina de Câmara Territorial. Base conferida: Art. 33, § 3º; Art. 45, § 2º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 33, § 3º; Art. 45, § 2º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"05-03_AlfaCon--organizacao-do-estado.pdf","documentTitle":"Organizacao do estado","publisher":"AlfaCon","documentSha256":"7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb","page":5,"itemNumber":10,"materialSlug":"constitucional-organizacao-estado-competencias","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":128,"statement":"A CF autoriza a divisão de Territórios em Municípios.","content_fingerprint":"a cf autoriza a divisao de territorios em municipios","audit":{"id":"2b3db9c3-178e-59e5-8ecb-6cb47fca8a45","document_sha256":"7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb","document_name":"05-03_AlfaCon--organizacao-do-estado.pdf","source_page":5,"item_number":11,"extracted_statement":"A CF autoriza a divisão de Territórios em Municípios.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"e5124536-3366-5cdb-a6b8-e626657eacd0","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"e5124536-3366-5cdb-a6b8-e626657eacd0","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb:11","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Organização do Estado","tested_topic":"Organização do Estado","question_text":"A CF autoriza a divisão de Territórios em Municípios.","official_answer":"C","explanation":"A Constituição admite divisão de territórios em municípios, aos quais se aplica, no que couber, a disciplina municipal pertinente. Base conferida: Art. 33, § 1º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 33, § 1º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"05-03_AlfaCon--organizacao-do-estado.pdf","documentTitle":"Organizacao do estado","publisher":"AlfaCon","documentSha256":"7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb","page":5,"itemNumber":11,"materialSlug":"constitucional-organizacao-estado-competencias","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":129,"statement":"Os Territórios não elegem senadores, mas elegem quatro deputados federais.","content_fingerprint":"os territorios nao elegem senadores mas elegem quatro deputados federais","audit":{"id":"c6a75267-fc91-5b5c-b6c8-aaed33df6eea","document_sha256":"7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb","document_name":"05-03_AlfaCon--organizacao-do-estado.pdf","source_page":5,"item_number":12,"extracted_statement":"Os Territórios não elegem senadores, mas elegem quatro deputados federais.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"29ab7077-bfb7-58d9-953b-1f11d779ef74","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"29ab7077-bfb7-58d9-953b-1f11d779ef74","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb:12","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Organização do Estado","tested_topic":"Organização do Estado","question_text":"Os Territórios não elegem senadores, mas elegem quatro deputados federais.","official_answer":"C","explanation":"Cada território elege quatro deputados federais. O Senado representa estados e Distrito Federal, não cria representação senatorial territorial equivalente. Base conferida: Art. 45, § 2º; Art. 46. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 45, § 2º; Art. 46"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"05-03_AlfaCon--organizacao-do-estado.pdf","documentTitle":"Organizacao do estado","publisher":"AlfaCon","documentSha256":"7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb","page":5,"itemNumber":12,"materialSlug":"constitucional-organizacao-estado-competencias","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":130,"statement":"Recusar fé aos documentos públicos inclui-se entre as vedações constitucionais de natureza federativa.","content_fingerprint":"recusar fe aos documentos publicos inclui se entre as vedacoes constitucionais de natureza federativa","audit":{"id":"30d89845-185f-5115-90eb-ca2dac70dbbd","document_sha256":"7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb","document_name":"05-03_AlfaCon--organizacao-do-estado.pdf","source_page":5,"item_number":13,"extracted_statement":"Recusar fé aos documentos públicos inclui-se entre as vedações constitucionais de natureza federativa.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"35423294-5e8f-5ab3-a7a9-56f6cb98b9af","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"35423294-5e8f-5ab3-a7a9-56f6cb98b9af","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb:13","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Organização do Estado","tested_topic":"Organização do Estado","question_text":"Recusar fé aos documentos públicos inclui-se entre as vedações constitucionais de natureza federativa.","official_answer":"C","explanation":"Recusar fé aos documentos públicos é vedação constitucional dirigida aos entes. Ela deve ser distinguida do exame legítimo de autenticidade e legalidade. Base conferida: Art. 19, II. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 19, II"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"05-03_AlfaCon--organizacao-do-estado.pdf","documentTitle":"Organizacao do estado","publisher":"AlfaCon","documentSha256":"7755809844d7bb3516745a901020c53ec6e4ebf7c99949ccda7ee3f3896f53cb","page":5,"itemNumber":13,"materialSlug":"constitucional-organizacao-estado-competencias","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":131,"statement":"A fim de integrar a organização, o planejamento e a execução de funções públicas de interesse comum, é permitido aos Estados, por intermédio de lei complementar, instituir regiões metropolitanas, aglomerações urbanas e microrregiões, constituídas por agrupamentos de Municípios limítrofes.","content_fingerprint":"a fim de integrar a organizacao o planejamento e a execucao de funcoes publicas de interesse comum e permitido aos estados por intermedio de lei complementar instituir regioes metropolitanas aglomeracoes urbanas e microrregioes constituidas por agrupamentos de municipios limitrofes","audit":{"id":"5741d168-124a-534e-81d5-4a63779b041c","document_sha256":"bf95a8497e51aecf0a4ef8fdfd09ea1bb993a245dad20e9928b96cbbbbfd2ba9","document_name":"05-04_AlfaCon--organizacao-do-estado_2.pdf","source_page":5,"item_number":1,"extracted_statement":"A fim de integrar a organização, o planejamento e a execução de funções públicas de interesse comum, é permitido aos Estados, por intermédio de lei complementar, instituir regiões metropolitanas, aglomerações urbanas e microrregiões, constituídas por agrupamentos de Municípios limítrofes.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"1ae79a8c-2c42-511c-aa45-da842b466b45","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"1ae79a8c-2c42-511c-aa45-da842b466b45","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:bf95a8497e51aecf0a4ef8fdfd09ea1bb993a245dad20e9928b96cbbbbfd2ba9:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Organização do Estado","tested_topic":"Organização do Estado","question_text":"A fim de integrar a organização, o planejamento e a execução de funções públicas de interesse comum, é permitido aos Estados, por intermédio de lei complementar, instituir regiões metropolitanas, aglomerações urbanas e microrregiões, constituídas por agrupamentos de Municípios limítrofes.","official_answer":"C","explanation":"A lei complementar estadual pode instituir os agrupamentos previstos para funções públicas de interesse comum. Não se cria um novo ente soberano. Base conferida: Art. 25, § 3º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 25, § 3º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"05-04_AlfaCon--organizacao-do-estado_2.pdf","documentTitle":"Organizacao do estado_2","publisher":"AlfaCon","documentSha256":"bf95a8497e51aecf0a4ef8fdfd09ea1bb993a245dad20e9928b96cbbbbfd2ba9","page":5,"itemNumber":1,"materialSlug":"constitucional-organizacao-estado-competencias","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":132,"statement":"Toda e qualquer terra devoluta pertence à União.","content_fingerprint":"toda e qualquer terra devoluta pertence a uniao","audit":{"id":"102b4fa6-d366-5119-94b3-128acba0e6d1","document_sha256":"bf95a8497e51aecf0a4ef8fdfd09ea1bb993a245dad20e9928b96cbbbbfd2ba9","document_name":"05-04_AlfaCon--organizacao-do-estado_2.pdf","source_page":5,"item_number":2,"extracted_statement":"Toda e qualquer terra devoluta pertence à União.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"a9cff503-7404-5e0f-bbcc-d6256000c1a6","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"a9cff503-7404-5e0f-bbcc-d6256000c1a6","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:bf95a8497e51aecf0a4ef8fdfd09ea1bb993a245dad20e9928b96cbbbbfd2ba9:2","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Organização do Estado","tested_topic":"Organização do Estado","question_text":"Toda e qualquer terra devoluta pertence à União.","official_answer":"E","explanation":"Nem toda terra devoluta pertence à União. É necessário distinguir o recorte federal e a atribuição das demais aos estados. Base conferida: Art. 20, II; Art. 26, IV. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 20, II; Art. 26, IV"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"05-04_AlfaCon--organizacao-do-estado_2.pdf","documentTitle":"Organizacao do estado_2","publisher":"AlfaCon","documentSha256":"bf95a8497e51aecf0a4ef8fdfd09ea1bb993a245dad20e9928b96cbbbbfd2ba9","page":5,"itemNumber":2,"materialSlug":"constitucional-organizacao-estado-competencias","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":133,"statement":"As terras devolutas pertencem aos Estados, com exceção das terras devolutas indispensáveis à defesa das fronteiras, das fortificações e construções militares, das vias federais de comunicação e à preservação ambiental, definidas em lei.","content_fingerprint":"as terras devolutas pertencem aos estados com excecao das terras devolutas indispensaveis a defesa das fronteiras das fortificacoes e construcoes militares das vias federais de comunicacao e a preservacao ambiental definidas em lei","audit":{"id":"cd6c6213-f174-51ca-b56a-1c5713ce4134","document_sha256":"bf95a8497e51aecf0a4ef8fdfd09ea1bb993a245dad20e9928b96cbbbbfd2ba9","document_name":"05-04_AlfaCon--organizacao-do-estado_2.pdf","source_page":5,"item_number":3,"extracted_statement":"As terras devolutas pertencem aos Estados, com exceção das terras devolutas indispensáveis à defesa das fronteiras, das fortificações e construções militares, das vias federais de comunicação e à preservação ambiental, definidas em lei.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"932f2fe5-f6f6-521a-ac65-6b6d9109f0e3","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"932f2fe5-f6f6-521a-ac65-6b6d9109f0e3","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:bf95a8497e51aecf0a4ef8fdfd09ea1bb993a245dad20e9928b96cbbbbfd2ba9:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"care