icaoCompilado.htm","artigo":"Art. 37, caput"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-01_AlfaCon--administracao-publica-principios-da-administracao-publica.pdf","documentTitle":"Administracao publica principios da administracao publica","publisher":"AlfaCon","documentSha256":"fe1b9fa1c54522a007a6c8e645710929010d5b9f87c8f102f51fc5c84fb27c17","page":5,"itemNumber":1,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":135,"statement":"A proibição de nomear parentes para ocupar cargos comissionados na Administração Pública é expressão da aplicação do princípio da moralidade.","content_fingerprint":"a proibicao de nomear parentes para ocupar cargos comissionados na administracao publica e expressao da aplicacao do principio da moralidade","audit":{"id":"f86ecd68-f8bb-5b86-89d8-9507037cddcd","document_sha256":"fe1b9fa1c54522a007a6c8e645710929010d5b9f87c8f102f51fc5c84fb27c17","document_name":"07-01_AlfaCon--administracao-publica-principios-da-administracao-publica.pdf","source_page":5,"item_number":2,"extracted_statement":"A proibição de nomear parentes para ocupar cargos comissionados na Administração Pública é expressão da aplicação do princípio da moralidade.","provided_answer":"C","current_answer":null,"review_status":"needs_review","review_note":"Exige a fonte oficial da SV 13 e condições do caso de nepotismo.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":136,"statement":"Os princípios explícitos da Administração Pública previstos na CF não se aplicam às sociedades de economia mista, em razão da natureza eminentemente empresarial desempenhada por essas entidades.","content_fingerprint":"os principios exp