:"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","documentTitle":"Administracao publica disposicoes gerais parte 2","publisher":"AlfaCon","documentSha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","page":3,"itemNumber":2,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":146,"statement":"O agente público condenado por ato de improbidade administrativa está sujeito à suspensão dos direitos políticos, à perda da função pública, à indisponibilidade de seus bens e ao ressarcimento dos prejuízos causados ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.","content_fingerprint":"o agente publico condenado por ato de improbidade administrativa esta sujeito a suspensao dos direitos politicos a perda da funcao publica a indisponibilidade de seus bens e ao ressarcimento dos prejuizos causados ao erario na forma e gradacao previstas em lei sem prejuizo da acao penal cabivel","audit":{"id":"ede0c452-a446-5f8f-aed9-43137cb6f106","document_sha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","document_name":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","source_page":4,"item_number":3,"extracted_statement":"O agente público condenado por ato de improbidade administrativa está sujeito à suspensão dos direitos políticos, à perda da função pública, à indisponibilidade de seus bens e ao ressarcimento dos prejuízos causados ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"83cfda87-0ab5-5d60-8aee-988c45eb3e0c","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"83cfda87-0ab5-5d60-8aee-988c45eb3e0c","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"O agente público condenado por ato de improbidade administrativa está sujeito à suspensão dos direitos políticos, à perda da função pública, à indisponibilidade de seus bens e ao ressarcimento dos prejuízos causados ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.","official_answer":"C","explanation":"O texto prevê consequências nas condições e gradação legais. Não se deve concluir que todas sejam automaticamente cumuladas em qualquer caso, nem confundir medida cautelar com pena. Base conferida: Art. 37, § 4º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, § 4º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","documentTitle":"Administracao publica disposicoes gerais parte 2","publisher":"AlfaCon","documentSha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","page":4,"itemNumber":3,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":147,"statement":"A regra da responsabilidade civil objetiva aplica-se indistintamente à Administração Direta e às entidades que compõem a Administração Indireta da União, dos Estados, do Distrito Federal e dos Municípios.","content_fingerprint":"a regra da responsabilidade civil objetiva aplica se indistintamente a administracao direta e as entidades que compoem a administracao indireta da uniao dos estados do distrito federal e dos municipios","audit":{"id":"a595fea1-aea8-5373-b850-ccae0cc4f031","document_sha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","document_name":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","source_page":4,"item_number":4,"extracted_statement":"A regra da responsabilidade civil objetiva aplica-se indistintamente à Administração Direta e às entidades que compõem a Administração Indireta da União, dos Estados, do Distrito Federal e dos Municípios.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"7ed161a3-d19f-5ea9-88f4-b2b09caa3713","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"7ed161a3-d19f-5ea9-88f4-b2b09caa3713","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a:4","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"A regra da responsabilidade civil objetiva aplica-se indistintamente à Administração Direta e às entidades que compõem a Administração Indireta da União, dos Estados, do Distrito Federal e dos Municípios.","official_answer":"E","explanation":"O recorte constitucional inclui pessoas jurídicas de direito público e de direito privado prestadoras de serviço público. Não cobre indistintamente toda entidade privada da administração indireta. Base conferida: Art. 37, § 6º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, § 6º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","documentTitle":"Administracao publica disposicoes gerais parte 2","publisher":"AlfaCon","documentSha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","page":4,"itemNumber":4,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":148,"statement":"A teoria da responsabilidade civil objetiva aplica-se às pessoas jurídicas de direito público, mas não às de direito privado, que, prestadoras, ou não, de serviços públicos, estão sujeitas à responsabilidade comum do direito civil.","content_fingerprint":"a teoria da responsabilidade civil objetiva aplica se as pessoas juridicas de direito publico mas nao as de direito privado que prestadoras ou nao de servicos publicos estao sujeitas a responsabilidade comum do direito civil","audit":{"id":"9e25fd5d-8598-59d0-a4bd-0eef98690384","document_sha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","document_name":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","source_page":4,"item_number":5,"extracted_statement":"A teoria da responsabilidade civil objetiva aplica-se às pessoas jurídicas de direito público, mas não às de direito privado, que, prestadoras, ou não, de serviços públicos, estão sujeitas à responsabilidade comum do direito civil.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"6439645f-214f-517e-9687-9927e34cc26f","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"6439645f-214f-517e-9687-9927e34cc26f","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a:5","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"A teoria da responsabilidade civil objetiva aplica-se às pessoas jurídicas de direito público, mas não às de direito privado, que, prestadoras, ou não, de serviços públicos, estão sujeitas à responsabilidade comum do direito civil.","official_answer":"E","explanation":"Pessoas jurídicas privadas prestadoras de serviço público estão no texto. Excluí-las genericamente da regra constitucional está incorreto. Base conferida: Art. 37, § 6º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, § 6º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","documentTitle":"Administracao publica disposicoes gerais parte 2","publisher":"AlfaCon","documentSha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","page":4,"itemNumber":5,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":149,"statement":"De acordo com a Constituição Federal, somente as pessoas jurídicas de direito público responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros.","content_fingerprint":"de acordo com a constituicao federal somente as pessoas juridicas de direito publico responderao pelos danos que seus agentes nessa qualidade causarem a terceiros","audit":{"id":"e5f1e647-fe44-5a90-b412-7fe6cdba7b9f","document_sha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","document_name":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","source_page":4,"item_number":6,"extracted_statement":"De acordo com a Constituição Federal, somente as pessoas jurídicas de direito público responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"39822a18-b2b2-5609-87b1-31b52bbc1a99","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"39822a18-b2b2-5609-87b1-31b52bbc1a99","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a:6","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"De acordo com a Constituição Federal, somente as pessoas jurídicas de direito público responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros.","official_answer":"E","explanation":"A Constituição não limita a regra às pessoas de direito público: também inclui privadas prestadoras de serviço público, nas condições descritas. Base conferida: Art. 37, § 6º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, § 6º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","documentTitle":"Administracao publica disposicoes gerais parte 2","publisher":"AlfaCon","documentSha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","page":4,"itemNumber":6,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":150,"statement":"Coaduna-se com a CF e atende ao princípio da publicidade a campanha de natureza educativa veiculada por órgão público, ainda que dela constem nomes ou símbolos que caracterizem promoção pessoal de autoridades.","content_fingerprint":"coaduna se com a cf e atende ao principio da publicidade a campanha de natureza educativa veiculada por orgao publico ainda que dela constem nomes ou simbolos que caracterizem promocao pessoal de autoridades","audit":{"id":"8f7d1cbd-5773-5d79-971f-6f67bca1e0fe","document_sha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","document_name":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","source_page":4,"item_number":7,"extracted_statement":"Coaduna-se com a CF e atende ao princípio da publicidade a campanha de natureza educativa veiculada por órgão público, ainda que dela constem nomes ou símbolos que caracterizem promoção pessoal de autoridades.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"c29bc463-542d-5143-98eb-10a3afdfc25c","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"c29bc463-542d-5143-98eb-10a3afdfc25c","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a:7","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"Coaduna-se com a CF e atende ao princípio da publicidade a campanha de natureza educativa veiculada por órgão público, ainda que dela constem nomes ou símbolos que caracterizem promoção pessoal de autoridades.","official_answer":"E","explanation":"Caráter educativo não autoriza promoção pessoal de autoridade. Exemplo: campanha institucional não pode servir de propaganda individual por nomes, símbolos ou imagens personalizadores. Base conferida: Art. 37, § 1º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, § 1º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-03_AlfaCon--administracao-publica-disposicoes-gerais-parte-2.pdf","documentTitle":"Administracao publica disposicoes gerais parte 2","publisher":"AlfaCon","documentSha256":"5af02647659f08fc5c826d251d75f4db833d5a2b9efcd3ba134a6620d1114f1a","page":4,"itemNumber":7,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":151,"statement":"Os cargos públicos devem ser plenamente acessíveis a brasileiros e a estrangeiros, podendo o edital do concurso estabelecer, justificadamente, requisitos apropriados às funções a serem desempenhadas.","content_fingerprint":"os cargos publicos devem ser plenamente acessiveis a brasileiros e a estrangeiros podendo o edital do concurso estabelecer justificadamente requisitos apropriados as funcoes a serem desempenhadas","audit":{"id":"c30812b8-54fd-502c-9b74-54108e47fa2f","document_sha256":"051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897","document_name":"07-04_AlfaCon--administracao-publica-servidores-publicos-parte-1.pdf","source_page":5,"item_number":1,"extracted_statement":"Os cargos públicos devem ser plenamente acessíveis a brasileiros e a estrangeiros, podendo o edital do concurso estabelecer, justificadamente, requisitos apropriados às funções a serem desempenhadas.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"f31d2e4a-b16b-5889-8fac-28a09d27d42d","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"f31d2e4a-b16b-5889-8fac-28a09d27d42d","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"Os cargos públicos devem ser plenamente acessíveis a brasileiros e a estrangeiros, podendo o edital do concurso estabelecer, justificadamente, requisitos apropriados às funções a serem desempenhadas.","official_answer":"E","explanation":"A Constituição refere requisitos estabelecidos em lei e o acesso de estrangeiros na forma da lei. O edital não substitui sozinho esse fundamento normativo. Base conferida: Art. 37, I. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, I"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-04_AlfaCon--administracao-publica-servidores-publicos-parte-1.pdf","documentTitle":"Administracao publica servidores publicos parte 1","publisher":"AlfaCon","documentSha256":"051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897","page":5,"itemNumber":1,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":152,"statement":"Embora os estrangeiros não gozem de direitos políticos, a Constituição Federal de 1988 (CF) previu para estes a possibilidade de acesso a cargos, empregos e funções públicas.","content_fingerprint":"embora os estrangeiros nao gozem de direitos politicos a constituicao federal de 1988 cf previu para estes a possibilidade de acesso a cargos empregos e funcoes publicas","audit":{"id":"6852b685-5722-5ef4-ac09-da109e1af12f","document_sha256":"051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897","document_name":"07-04_AlfaCon--administracao-publica-servidores-publicos-parte-1.pdf","source_page":5,"item_number":2,"extracted_statement":"Embora os estrangeiros não gozem de direitos políticos, a Constituição Federal de 1988 (CF) previu para estes a possibilidade de acesso a cargos, empregos e funções públicas.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"7d272ce8-26c2-5aca-8fe7-32fef2d288e2","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"7d272ce8-26c2-5aca-8fe7-32fef2d288e2","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897:2","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"Embora os estrangeiros não gozem de direitos políticos, a Constituição Federal de 1988 (CF) previu para estes a possibilidade de acesso a cargos, empregos e funções públicas.","official_answer":"C","explanation":"O texto admite acesso de estrangeiros na forma da lei. Isso não os transforma automaticamente em nacionais ou lhes confere todo direito político. Base conferida: Art. 37, I. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, I"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-04_AlfaCon--administracao-publica-servidores-publicos-parte-1.pdf","documentTitle":"Administracao publica servidores publicos parte 1","publisher":"AlfaCon","documentSha256":"051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897","page":5,"itemNumber":2,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":153,"statement":"Destinam-se apenas às atribuições de direção, chefia e assessoramento as funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo bem como os cargos em comissão, a serem preenchidos por servidores de carreira, nos casos, nas condições e nos percentuais mínimos previstos em lei.","content_fingerprint":"destinam se apenas as atribuicoes de direcao chefia e assessoramento as funcoes de confianca exercidas exclusivamente por servidores ocupantes de cargo efetivo bem como os cargos em comissao a serem preenchidos por servidores de carreira nos casos nas condicoes e nos percentuais minimos previstos em lei","audit":{"id":"ea18332e-19e7-5d03-9e30-df683252419c","document_sha256":"051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897","document_name":"07-04_AlfaCon--administracao-publica-servidores-publicos-parte-1.pdf","source_page":6,"item_number":3,"extracted_statement":"Destinam-se apenas às atribuições de direção, chefia e assessoramento as funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo bem como os cargos em comissão, a serem preenchidos por servidores de carreira, nos casos, nas condições e nos percentuais mínimos previstos em lei.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"d9ced713-202e-5555-9a73-5ea8ebb4a4d9","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"d9ced713-202e-5555-9a73-5ea8ebb4a4d9","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"Destinam-se apenas às atribuições de direção, chefia e assessoramento as funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo bem como os cargos em comissão, a serem preenchidos por servidores de carreira, nos casos, nas condições e nos percentuais mínimos previstos em lei.","official_answer":"C","explanation":"Funções de confiança e cargos em comissão têm destinação de direção, chefia e assessoramento. Ocupação e percentuais devem observar as distinções do inciso. Base conferida: Art. 37, V. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, V"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-04_AlfaCon--administracao-publica-servidores-publicos-parte-1.pdf","documentTitle":"Administracao publica servidores publicos parte 1","publisher":"AlfaCon","documentSha256":"051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897","page":6,"itemNumber":3,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":154,"statement":"As funções de confiança devem ser exercidas exclusivamente por servidores ocupantes de cargo efetivo","content_fingerprint":"as funcoes de confianca devem ser exercidas exclusivamente por servidores ocupantes de cargo efetivo","audit":{"id":"19b42dfd-aa93-5cb2-93e9-51099df0efd1","document_sha256":"051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897","document_name":"07-04_AlfaCon--administracao-publica-servidores-publicos-parte-1.pdf","source_page":6,"item_number":4,"extracted_statement":"As funções de confiança devem ser exercidas exclusivamente por servidores ocupantes de cargo efetivo","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"92192e8b-10a3-52b2-9f6e-31007afb5256","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"92192e8b-10a3-52b2-9f6e-31007afb5256","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897:4","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"As funções de confiança devem ser exercidas exclusivamente por servidores ocupantes de cargo efetivo","official_answer":"C","explanation":"A função de confiança exige servidor ocupante de cargo efetivo. Não se confunde com qualquer hipótese de cargo em comissão. Base conferida: Art. 37, V. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, V"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-04_AlfaCon--administracao-publica-servidores-publicos-parte-1.pdf","documentTitle":"Administracao publica servidores publicos parte 1","publisher":"AlfaCon","documentSha256":"051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897","page":6,"itemNumber":4,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":155,"statement":"Funções, cargos e empregos públicos não são acessíveis aos estrangeiros.","content_fingerprint":"funcoes cargos e empregos publicos nao sao acessiveis aos estrangeiros","audit":{"id":"79c903ee-669d-56c0-a141-6eb324cebb28","document_sha256":"051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897","document_name":"07-04_AlfaCon--administracao-publica-servidores-publicos-parte-1.pdf","source_page":6,"item_number":5,"extracted_statement":"Funções, cargos e empregos públicos não são acessíveis aos estrangeiros.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"86fc984c-4422-5372-824f-910ef6a17be1","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"86fc984c-4422-5372-824f-910ef6a17be1","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897:5","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"Funções, cargos e empregos públicos não são acessíveis aos estrangeiros.","official_answer":"E","explanation":"A Constituição prevê acesso de estrangeiros na forma da lei. Uma proibição absoluta ignora essa possibilidade expressa. Base conferida: Art. 37, I. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, I"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-04_AlfaCon--administracao-publica-servidores-publicos-parte-1.pdf","documentTitle":"Administracao publica servidores publicos parte 1","publisher":"AlfaCon","documentSha256":"051f1b4829923f9072c781491555446ae26075bfd2fc16ee33d434e18de20897","page":6,"itemNumber":5,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":156,"statement":"Os servidores públicos gozam de todos os direitos sociais previstos no texto constitucional para os trabalhadores da iniciativa privada.","content_fingerprint":"os servidores publicos gozam de todos os direitos sociais previstos no texto constitucional para os trabalhadores da iniciativa privada","audit":{"id":"200ecb8e-3585-5f9e-97ac-5e176449b7f7","document_sha256":"2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff","document_name":"07-05_AlfaCon--administracao-publica-servidores-publicos-parte-2.pdf","source_page":6,"item_number":1,"extracted_statement":"Os servidores públicos gozam de todos os direitos sociais previstos no texto constitucional para os trabalhadores da iniciativa privada.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"44455a5f-71d4-5143-a4df-cd6a24c222a0","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"44455a5f-71d4-5143-a4df-cd6a24c222a0","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"Os servidores públicos gozam de todos os direitos sociais previstos no texto constitucional para os trabalhadores da iniciativa privada.","official_answer":"E","explanation":"A remissão aos direitos do art. 7º é específica. Não há importação automática de todo o catálogo para todo vínculo público. Base conferida: Art. 39, § 3º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 39, § 3º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-05_AlfaCon--administracao-publica-servidores-publicos-parte-2.pdf","documentTitle":"Administracao publica servidores publicos parte 2","publisher":"AlfaCon","documentSha256":"2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff","page":6,"itemNumber":1,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":157,"statement":"A CF não previu o direito de greve nem o direito à livre associação aos servidores públicos.","content_fingerprint":"a cf nao previu o direito de greve nem o direito a livre associacao aos servidores publicos","audit":{"id":"da0c1a60-eb98-5cc2-b096-d9956882e78d","document_sha256":"2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff","document_name":"07-05_AlfaCon--administracao-publica-servidores-publicos-parte-2.pdf","source_page":6,"item_number":2,"extracted_statement":"A CF não previu o direito de greve nem o direito à livre associação aos servidores públicos.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"91fe96c9-6603-544c-8316-0c907928d294","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"91fe96c9-6603-544c-8316-0c907928d294","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff:2","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"A CF não previu o direito de greve nem o direito à livre associação aos servidores públicos.","official_answer":"E","explanation":"O texto prevê associação sindical e greve, com disciplina própria. Isso não significa autorização irrestrita para todas as carreiras ou eliminação das restrições pertinentes. Base conferida: Art. 37, VI e VII. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, VI e VII"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-05_AlfaCon--administracao-publica-servidores-publicos-parte-2.pdf","documentTitle":"Administracao publica servidores publicos parte 2","publisher":"AlfaCon","documentSha256":"2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff","page":6,"itemNumber":2,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":158,"statement":"A norma constitucional que assegura o direito de greve aos servidores públicos tem eficácia contida, uma vez que a produção de seus efeitos depende de normas infraconstitucionais integrativas.","content_fingerprint":"a norma constitucional que assegura o direito de greve aos servidores publicos tem eficacia contida uma vez que a producao de seus efeitos depende de normas infraconstitucionais integrativas","audit":{"id":"902ca06b-b7e9-53fb-b8e1-00179fd86d75","document_sha256":"2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff","document_name":"07-05_AlfaCon--administracao-publica-servidores-publicos-parte-2.pdf","source_page":6,"item_number":3,"extracted_statement":"A norma constitucional que assegura o direito de greve aos servidores públicos tem eficácia contida, uma vez que a produção de seus efeitos depende de normas infraconstitucionais integrativas.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"f19cb321-9255-59bf-b712-15c05000323f","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"f19cb321-9255-59bf-b712-15c05000323f","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"A norma constitucional que assegura o direito de greve aos servidores públicos tem eficácia contida, uma vez que a produção de seus efeitos depende de normas infraconstitucionais integrativas.","official_answer":"E","explanation":"A classificação didática da norma dependente de regulamentação não é a de eficácia contida descrita. O exercício concreto exige também considerar a jurisprudência e a carreira, sem autorização universal de greve. Base conferida: Art. 37, VII. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, VII"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-05_AlfaCon--administracao-publica-servidores-publicos-parte-2.pdf","documentTitle":"Administracao publica servidores publicos parte 2","publisher":"AlfaCon","documentSha256":"2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff","page":6,"itemNumber":3,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":159,"statement":"A CF autoriza a acumulação remunerada de dois cargos de técnico administrativo, desde que haja compatibilidade de horários e seja observado o teto constitucional da remuneração do serviço público.","content_fingerprint":"a cf autoriza a acumulacao remunerada de dois cargos de tecnico administrativo desde que haja compatibilidade de horarios e seja observado o teto constitucional da remuneracao do servico publico","audit":{"id":"de81885b-41d2-5375-8926-3b53f6251769","document_sha256":"2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff","document_name":"07-05_AlfaCon--administracao-publica-servidores-publicos-parte-2.pdf","source_page":6,"item_number":4,"extracted_statement":"A CF autoriza a acumulação remunerada de dois cargos de técnico administrativo, desde que haja compatibilidade de horários e seja observado o teto constitucional da remuneração do serviço público.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"b139e292-9f81-5bdc-845b-656eb841018e","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"b139e292-9f81-5bdc-845b-656eb841018e","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff:4","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"A CF autoriza a acumulação remunerada de dois cargos de técnico administrativo, desde que haja compatibilidade de horários e seja observado o teto constitucional da remuneração do serviço público.","official_answer":"E","explanation":"Compatibilidade de horários é condição, mas não cria nova hipótese geral de dois cargos de técnico administrativo fora das exceções constitucionais. Base conferida: Art. 37, XVI. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 37, XVI"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-05_AlfaCon--administracao-publica-servidores-publicos-parte-2.pdf","documentTitle":"Administracao publica servidores publicos parte 2","publisher":"AlfaCon","documentSha256":"2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff","page":6,"itemNumber":4,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":160,"statement":"O servidor abrangido pelo art. 38 eleito vereador pode manter os exercícios quando houver compatibilidade de horários; nas demais hipóteses de mandato, devem ser observadas as regras constitucionais de afastamento e remuneração.","content_fingerprint":"o servidor abrangido pelo art 38 eleito vereador pode manter os exercicios quando houver compatibilidade de horarios nas demais hipoteses de mandato devem ser observadas as regras constitucionais de afastamento e remuneracao","audit":{"id":"e2823aa0-c0be-5f98-abdf-753d2e68f83b","document_sha256":"2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff","document_name":"07-05_AlfaCon--administracao-publica-servidores-publicos-parte-2.pdf","source_page":6,"item_number":5,"extracted_statement":"Servidor público da Administração direta, autárquica ou fundacional eleito vereador poderá acumular o exercício de seu cargo público com o do mandato. Entretanto, sendo ele eleito para os demais cargos eletivos, deverá ficar afastado de sua função, de seu cargo ou de seu emprego públicos.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático. Redação delimitada/atualizada para evitar ambiguidade ou regra superada.","question_table":"curated_question_catalog","question_id":"544715fa-16ed-5ab9-af56-40f82a895301","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"544715fa-16ed-5ab9-af56-40f82a895301","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff:5","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Administração pública constitucional","tested_topic":"Administração pública constitucional","question_text":"O servidor abrangido pelo art. 38 eleito vereador pode manter os exercícios quando houver compatibilidade de horários; nas demais hipóteses de mandato, devem ser observadas as regras constitucionais de afastamento e remuneração.","official_answer":"C","explanation":"A acumulação com mandato de vereador pressupõe compatibilidade. A adaptação explicita essa condição; para os demais mandatos, devem ser observadas as soluções constitucionais de afastamento e remuneração. Base conferida: Art. 38. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 38"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"07-05_AlfaCon--administracao-publica-servidores-publicos-parte-2.pdf","documentTitle":"Administracao publica servidores publicos parte 2","publisher":"AlfaCon","documentSha256":"2dcee81c688e8bbff8500f76cc828107e0b6aeea9ad1622b441ba5ec44a132ff","page":6,"itemNumber":5,"materialSlug":"constitucional-administracao-publica-constituicao","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":161,"statement":"É permitido aos servidores do Poder Judiciário cumprir atos de expediente, sendo-lhes vedado realizar atos administrativos","content_fingerprint":"e permitido aos servidores do poder judiciario cumprir atos de expediente sendo lhes vedado realizar atos administrativos","audit":{"id":"04d5a272-d9d5-55ab-9ef0-5b9c31ba36c6","document_sha256":"216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75","document_name":"08-01_AlfaCon--poder-judiciario-orgaos-do-poder-judiciario-disposicoes-gerais.pdf","source_page":5,"item_number":1,"extracted_statement":"É permitido aos servidores do Poder Judiciário cumprir atos de expediente, sendo-lhes vedado realizar atos administrativos","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"2632ed5e-6e67-5867-a6ea-cd6dc6781bec","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"2632ed5e-6e67-5867-a6ea-cd6dc6781bec","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Judiciário: garantias e carreira","tested_topic":"Judiciário: garantias e carreira","question_text":"É permitido aos servidores do Poder Judiciário cumprir atos de expediente, sendo-lhes vedado realizar atos administrativos","official_answer":"E","explanation":"A Constituição prevê delegação a servidores de atos administrativos e de mero expediente sem caráter decisório. A proibição genérica de atos administrativos está incorreta. Base conferida: Art. 93, XIV. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 93, XIV"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-01_AlfaCon--poder-judiciario-orgaos-do-poder-judiciario-disposicoes-gerais.pdf","documentTitle":"Poder judiciario orgaos do poder judiciario disposicoes gerais","publisher":"AlfaCon","documentSha256":"216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75","page":5,"itemNumber":1,"materialSlug":"constitucional-judiciario-garantias-carreira","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":162,"statement":"O Conselho Nacional de Justiça (CNJ) é órgão do Poder Executivo, embora atue como instância correcional do Poder Judiciário.","content_fingerprint":"o conselho nacional de justica cnj e orgao do poder executivo embora atue como instancia correcional do poder judiciario","audit":{"id":"e45a6e53-946f-5802-910e-eaa970998918","document_sha256":"216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75","document_name":"08-01_AlfaCon--poder-judiciario-orgaos-do-poder-judiciario-disposicoes-gerais.pdf","source_page":5,"item_number":2,"extracted_statement":"O Conselho Nacional de Justiça (CNJ) é órgão do Poder Executivo, embora atue como instância correcional do Poder Judiciário.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"24724634-be0d-5f5c-944a-4bc6c08dae72","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"24724634-be0d-5f5c-944a-4bc6c08dae72","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75:2","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Judiciário: garantias e carreira","tested_topic":"Judiciário: garantias e carreira","question_text":"O Conselho Nacional de Justiça (CNJ) é órgão do Poder Executivo, embora atue como instância correcional do Poder Judiciário.","official_answer":"E","explanation":"O CNJ integra o Judiciário, com atribuições constitucionais próprias. Não é órgão do Executivo. Base conferida: Art. 92, I-A; Art. 103-B. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 92, I-A; Art. 103-B"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-01_AlfaCon--poder-judiciario-orgaos-do-poder-judiciario-disposicoes-gerais.pdf","documentTitle":"Poder judiciario orgaos do poder judiciario disposicoes gerais","publisher":"AlfaCon","documentSha256":"216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75","page":5,"itemNumber":2,"materialSlug":"constitucional-judiciario-garantias-carreira","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":163,"statement":"A cláusula de reserva de plenário determina que somente pelo voto da maioria absoluta dos membros do tribunal ou do respectivo órgão especial pode ser declarada a inconstitucionalidade de lei ou ato normativo do poder público.","content_fingerprint":"a clausula de reserva de plenario determina que somente pelo voto da maioria absoluta dos membros do tribunal ou do respectivo orgao especial pode ser declarada a inconstitucionalidade de lei ou ato normativo do poder publico","audit":{"id":"044642a3-a90f-56c9-8419-e3870ddcf253","document_sha256":"216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75","document_name":"08-01_AlfaCon--poder-judiciario-orgaos-do-poder-judiciario-disposicoes-gerais.pdf","source_page":5,"item_number":3,"extracted_statement":"A cláusula de reserva de plenário determina que somente pelo voto da maioria absoluta dos membros do tribunal ou do respectivo órgão especial pode ser declarada a inconstitucionalidade de lei ou ato normativo do poder público.","provided_answer":"C","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"f64a4f93-0f9d-510b-9585-b0d9a8426d5f","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"f64a4f93-0f9d-510b-9585-b0d9a8426d5f","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Judiciário: garantias e carreira","tested_topic":"Judiciário: garantias e carreira","question_text":"A cláusula de reserva de plenário determina que somente pelo voto da maioria absoluta dos membros do tribunal ou do respectivo órgão especial pode ser declarada a inconstitucionalidade de lei ou ato normativo do poder público.","official_answer":"C","explanation":"A declaração por tribunal exige maioria absoluta dos seus membros ou do órgão especial. Não se trata de maioria simples de qualquer órgão fracionário. Base conferida: Art. 97. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 97"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-01_AlfaCon--poder-judiciario-orgaos-do-poder-judiciario-disposicoes-gerais.pdf","documentTitle":"Poder judiciario orgaos do poder judiciario disposicoes gerais","publisher":"AlfaCon","documentSha256":"216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75","page":5,"itemNumber":3,"materialSlug":"constitucional-judiciario-garantias-carreira","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":164,"statement":"O ingresso na carreira da magistratura ocorrerá mediante concurso público de provas e títulos, sem a participação da Ordem dos Advogados do Brasil.","content_fingerprint":"o ingresso na carreira da magistratura ocorrera mediante concurso publico de provas e titulos sem a participacao da ordem dos advogados do brasil","audit":{"id":"95795066-898c-506c-9984-3d955b9dfccc","document_sha256":"216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75","document_name":"08-01_AlfaCon--poder-judiciario-orgaos-do-poder-judiciario-disposicoes-gerais.pdf","source_page":5,"item_number":4,"extracted_statement":"O ingresso na carreira da magistratura ocorrerá mediante concurso público de provas e títulos, sem a participação da Ordem dos Advogados do Brasil.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"a6f0644f-f253-595e-a62f-96f402d1f4c4","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"a6f0644f-f253-595e-a62f-96f402d1f4c4","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75:4","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Judiciário: garantias e carreira","tested_topic":"Judiciário: garantias e carreira","question_text":"O ingresso na carreira da magistratura ocorrerá mediante concurso público de provas e títulos, sem a participação da Ordem dos Advogados do Brasil.","official_answer":"E","explanation":"A Constituição prevê participação da OAB em todas as fases do concurso. O enunciado exclui requisito expresso. Base conferida: Art. 93, I. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 93, I"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-01_AlfaCon--poder-judiciario-orgaos-do-poder-judiciario-disposicoes-gerais.pdf","documentTitle":"Poder judiciario orgaos do poder judiciario disposicoes gerais","publisher":"AlfaCon","documentSha256":"216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75","page":5,"itemNumber":4,"materialSlug":"constitucional-judiciario-garantias-carreira","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":165,"statement":"Consoante o teor literal da Constituição Federal (CF), todas as decisões do Poder Judiciário serão fundamentadas.","content_fingerprint":"consoante o teor literal da constituicao federal cf todas as decisoes do poder judiciario serao fundamentadas","audit":{"id":"e68358f5-196b-5f2b-a7f8-3b4727e874f7","document_sha256":"216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75","document_name":"08-01_AlfaCon--poder-judiciario-orgaos-do-poder-judiciario-disposicoes-gerais.pdf","source_page":5,"item_number":5,"extracted_statement":"Consoante o teor literal da Constituição Federal (CF), todas as decisões do Poder Judiciário serão fundamentadas.","provided_answer":"C","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"5cf0b2b9-0d51-5dcf-bbb8-7e73910e2fae","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"5cf0b2b9-0d51-5dcf-bbb8-7e73910e2fae","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75:5","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Judiciário: garantias e carreira","tested_topic":"Judiciário: garantias e carreira","question_text":"Consoante o teor literal da Constituição Federal (CF), todas as decisões do Poder Judiciário serão fundamentadas.","official_answer":"C","explanation":"O dever constitucional de fundamentação alcança as decisões indicadas no texto. Publicidade e fundamentação não são categorias substituíveis. Base conferida: Art. 93, IX e X. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 93, IX e X"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-01_AlfaCon--poder-judiciario-orgaos-do-poder-judiciario-disposicoes-gerais.pdf","documentTitle":"Poder judiciario orgaos do poder judiciario disposicoes gerais","publisher":"AlfaCon","documentSha256":"216b195020dfb3915a26e9e5b523f32bad8a5cb88dfa173eca2e0c75f6b21c75","page":5,"itemNumber":5,"materialSlug":"constitucional-judiciario-garantias-carreira","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":166,"statement":"No primeiro grau, o juiz adquire vitaliciedade após dois anos de exercício; um ministro do STF que não era magistrado de primeiro grau não precisa cumprir esse estágio bienal no Supremo.","content_fingerprint":"no primeiro grau o juiz adquire vitaliciedade apos dois anos de exercicio um ministro do stf que nao era magistrado de primeiro grau nao precisa cumprir esse estagio bienal no supremo","audit":{"id":"64e3c532-8440-5d13-ad0a-72f3e0d4b44a","document_sha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","document_name":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","source_page":4,"item_number":1,"extracted_statement":"O magistrado da justiça de primeiro grau adquire vitaliciedade após dois anos de exercício, e os ministros de tribunais superiores que não sejam egressos da magistratura de primeiro grau adquirem-na com a posse no cargo de ministro.","provided_answer":"C","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático. Redação delimitada/atualizada para evitar ambiguidade ou regra superada.","question_table":"curated_question_catalog","question_id":"ce1c7549-9a92-55ca-8c3d-50154eafd64f","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"ce1c7549-9a92-55ca-8c3d-50154eafd64f","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Judiciário: garantias e carreira","tested_topic":"Judiciário: garantias e carreira","question_text":"No primeiro grau, o juiz adquire vitaliciedade após dois anos de exercício; um ministro do STF que não era magistrado de primeiro grau não precisa cumprir esse estágio bienal no Supremo.","official_answer":"C","explanation":"No primeiro grau a aquisição ocorre após dois anos; nos demais casos, a garantia não depende de repetir esse estágio. É necessário distinguir a forma de ingresso e a perda do cargo. Base conferida: Art. 95, I. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 95, I"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","documentTitle":"Poder judiciario quinto constitucional garantias e impedimentos","publisher":"AlfaCon","documentSha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","page":4,"itemNumber":1,"materialSlug":"constitucional-judiciario-garantias-carreira","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":167,"statement":"De acordo com o STF, a garantia da inamovibilidade é reconhecida ao magistrado titular, mas não ao substituto.","content_fingerprint":"de acordo com o stf a garantia da inamovibilidade e reconhecida ao magistrado titular mas nao ao substituto","audit":{"id":"4e95fdd5-bb06-51d7-91a1-fdd4eaea6116","document_sha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","document_name":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","source_page":4,"item_number":2,"extracted_statement":"De acordo com o STF, a garantia da inamovibilidade é reconhecida ao magistrado titular, mas não ao substituto.","provided_answer":"E","current_answer":null,"review_status":"needs_review","review_note":"Exige precedente oficial sobre inamovibilidade do juiz substituto.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":168,"statement":"No primeiro grau, a vitaliciedade só será adquirida após, no mínimo, três anos de exercício.","content_fingerprint":"no primeiro grau a vitaliciedade so sera adquirida apos no minimo tres anos de exercicio","audit":{"id":"6ae0609f-c255-54fa-8ac7-2d7dd26b90af","document_sha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","document_name":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","source_page":4,"item_number":3,"extracted_statement":"No primeiro grau, a vitaliciedade só será adquirida após, no mínimo, três anos de exercício.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"67402f9d-9411-5a7b-b33e-3659ed4c5173","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"67402f9d-9411-5a7b-b33e-3659ed4c5173","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Judiciário: garantias e carreira","tested_topic":"Judiciário: garantias e carreira","question_text":"No primeiro grau, a vitaliciedade só será adquirida após, no mínimo, três anos de exercício.","official_answer":"E","explanation":"O prazo constitucional de primeiro grau é dois anos, não três. Não se deve copiar o prazo de estabilidade do servidor do art. 41. Base conferida: Art. 95, I. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 95, I"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","documentTitle":"Poder judiciario quinto constitucional garantias e impedimentos","publisher":"AlfaCon","documentSha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","page":4,"itemNumber":3,"materialSlug":"constitucional-judiciario-garantias-carreira","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":169,"statement":"A regra constitucional que proíbe o magistrado de exercer a advocacia no juízo ou no tribunal do qual se tenha afastado, antes de decorrido o período de três anos, contados do afastamento do cargo, aplica-se tanto ao Poder Judiciário estadual quanto ao federal de qualquer instância, incluindo-se o STF, o STJ e os demais tribunais superiores.","content_fingerprint":"a regra constitucional que proibe o magistrado de exercer a advocacia no juizo ou no tribunal do qual se tenha afastado antes de decorrido o periodo de tres anos contados do afastamento do cargo aplica se tanto ao poder judiciario estadual quanto ao federal de qualquer instancia incluindo se o stf o stj e os demais tribunais superiores","audit":{"id":"f5e54193-27ae-506d-8444-89f16715fae3","document_sha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","document_name":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","source_page":4,"item_number":4,"extracted_statement":"A regra constitucional que proíbe o magistrado de exercer a advocacia no juízo ou no tribunal do qual se tenha afastado, antes de decorrido o período de três anos, contados do afastamento do cargo, aplica-se tanto ao Poder Judiciário estadual quanto ao federal de qualquer instância, incluindo-se o STF, o STJ e os demais tribunais superiores.","provided_answer":"C","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"75c0d4ba-b411-563e-9bcb-6f6855691202","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"75c0d4ba-b411-563e-9bcb-6f6855691202","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080:4","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Judiciário: garantias e carreira","tested_topic":"Judiciário: garantias e carreira","question_text":"A regra constitucional que proíbe o magistrado de exercer a advocacia no juízo ou no tribunal do qual se tenha afastado, antes de decorrido o período de três anos, contados do afastamento do cargo, aplica-se tanto ao Poder Judiciário estadual quanto ao federal de qualquer instância, incluindo-se o STF, o STJ e os demais tribunais superiores.","official_answer":"C","explanation":"A vedação no juízo ou tribunal de afastamento dura três anos nas condições constitucionais. Não há exceção genérica por ser tribunal federal ou superior. Base conferida: Art. 95, parágrafo único, V. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 95, parágrafo único, V"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","documentTitle":"Poder judiciario quinto constitucional garantias e impedimentos","publisher":"AlfaCon","documentSha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","page":4,"itemNumber":4,"materialSlug":"constitucional-judiciario-garantias-carreira","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":170,"statement":"De acordo com a CF, a atividade político-partidária não é vedada aos juízes, que poderão exercê-la mediante autorização prévia do tribunal a que se vinculem.","content_fingerprint":"de acordo com a cf a atividade politico partidaria nao e vedada aos juizes que poderao exerce la mediante autorizacao previa do tribunal a que se vinculem","audit":{"id":"0c447f29-dda6-5ff3-895d-4923e8173207","document_sha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","document_name":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","source_page":4,"item_number":5,"extracted_statement":"De acordo com a CF, a atividade político-partidária não é vedada aos juízes, que poderão exercê-la mediante autorização prévia do tribunal a que se vinculem.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"14758b0f-c5e6-5a6d-81e6-cad5db22f8bb","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"14758b0f-c5e6-5a6d-81e6-cad5db22f8bb","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080:5","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Judiciário: garantias e carreira","tested_topic":"Judiciário: garantias e carreira","question_text":"De acordo com a CF, a atividade político-partidária não é vedada aos juízes, que poderão exercê-la mediante autorização prévia do tribunal a que se vinculem.","official_answer":"E","explanation":"Atividade político-partidária é vedada aos juízes. Uma autorização interna não afasta essa proibição constitucional. Base conferida: Art. 95, parágrafo único, III. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 95, parágrafo único, III"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","documentTitle":"Poder judiciario quinto constitucional garantias e impedimentos","publisher":"AlfaCon","documentSha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","page":4,"itemNumber":5,"materialSlug":"constitucional-judiciario-garantias-carreira","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":171,"statement":"A CF conferiu autonomia institucional ao Poder Judiciário, que recebeu, entre outras, garantias de autonomia orgânico administrativa, financeira e funcional, além de ter salvaguardada a independência dos órgãos judiciários.","content_fingerprint":"a cf conferiu autonomia institucional ao poder judiciario que recebeu entre outras garantias de autonomia organico administrativa financeira e funcional alem de ter salvaguardada a independencia dos orgaos judiciarios","audit":{"id":"f3097782-2b8e-5bf7-9e70-85c66330671d","document_sha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","document_name":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","source_page":4,"item_number":6,"extracted_statement":"A CF conferiu autonomia institucional ao Poder Judiciário, que recebeu, entre outras, garantias de autonomia orgânico administrativa, financeira e funcional, além de ter salvaguardada a independência dos órgãos judiciários.","provided_answer":"C","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"53f35982-dd75-5366-8911-476daf7ff720","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"53f35982-dd75-5366-8911-476daf7ff720","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080:6","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Judiciário: garantias e carreira","tested_topic":"Judiciário: garantias e carreira","question_text":"A CF conferiu autonomia institucional ao Poder Judiciário, que recebeu, entre outras, garantias de autonomia orgânico administrativa, financeira e funcional, além de ter salvaguardada a independência dos órgãos judiciários.","official_answer":"C","explanation":"Autonomia institucional e independência têm proteção constitucional, sem eliminar limites orçamentários, competências e controles aplicáveis. Base conferida: Arts. 96 e 99. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Arts. 96 e 99"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-02_AlfaCon--poder-judiciario-quinto-constitucional-garantias-e-impedimentos.pdf","documentTitle":"Poder judiciario quinto constitucional garantias e impedimentos","publisher":"AlfaCon","documentSha256":"8c21f6368c64045152af06361e4595d1db82ce26fb84c923d2a6e378f6ee5080","page":4,"itemNumber":6,"materialSlug":"constitucional-judiciario-garantias-carreira","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":172,"statement":"O Conselho Nacional de Justiça tem competência para controlar a atuação administrativa e financeira do Poder Judiciário e da Defensoria Pública.","content_fingerprint":"o conselho nacional de justica tem competencia para controlar a atuacao administrativa e financeira do poder judiciario e da defensoria publica","audit":{"id":"84cdfc8d-da4e-50c2-ab5e-6747df1de9f9","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":6,"item_number":1,"extracted_statement":"O Conselho Nacional de Justiça tem competência para controlar a atuação administrativa e financeira do Poder Judiciário e da Defensoria Pública.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"f879ef85-aae2-5c5a-a19d-ccc9077f2c28","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"f879ef85-aae2-5c5a-a19d-ccc9077f2c28","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"O Conselho Nacional de Justiça tem competência para controlar a atuação administrativa e financeira do Poder Judiciário e da Defensoria Pública.","official_answer":"E","explanation":"O âmbito de controle do CNJ não inclui genericamente a Defensoria Pública, que possui disciplina própria de autonomia e controle. Base conferida: Art. 103-B, § 4º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 103-B, § 4º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","documentTitle":"Poder judiciario composicao conselho nacional de justica","publisher":"AlfaCon","documentSha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","page":6,"itemNumber":1,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":173,"statement":"O Conselho Nacional de Justiça possui, além da função administrativa, a função jurisdicional.","content_fingerprint":"o conselho nacional de justica possui alem da funcao administrativa a funcao jurisdicional","audit":{"id":"104b6388-8425-50ba-8f75-c84bcf91ec40","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":6,"item_number":2,"extracted_statement":"O Conselho Nacional de Justiça possui, além da função administrativa, a função jurisdicional.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"21d23771-e1c6-5ab5-881d-ea252e683b58","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"21d23771-e1c6-5ab5-881d-ea252e683b58","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504:2","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"O Conselho Nacional de Justiça possui, além da função administrativa, a função jurisdicional.","official_answer":"E","explanation":"A inclusão no Judiciário não torna o Conselho órgão de julgamento jurisdicional comum. Suas atribuições de controle têm âmbito próprio. Base conferida: Art. 103-B. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 103-B"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","documentTitle":"Poder judiciario composicao conselho nacional de justica","publisher":"AlfaCon","documentSha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","page":6,"itemNumber":2,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":174,"statement":"Embora seja, conforme disposto na CF, órgão do Poder Judiciário, o CNJ não exerce atividade judicante, não lhe sendo permitido reexaminar atos de conteúdo jurisdicional formalizados por magistrados ou tribunais.","content_fingerprint":"embora seja conforme disposto na cf orgao do poder judiciario o cnj nao exerce atividade judicante nao lhe sendo permitido reexaminar atos de conteudo jurisdicional formalizados por magistrados ou tribunais","audit":{"id":"f0a4a805-43fd-5954-a909-cc6f4043aee1","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":6,"item_number":3,"extracted_statement":"Embora seja, conforme disposto na CF, órgão do Poder Judiciário, o CNJ não exerce atividade judicante, não lhe sendo permitido reexaminar atos de conteúdo jurisdicional formalizados por magistrados ou tribunais.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"85378794-3a4b-5195-ad99-5d412786f5c8","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"85378794-3a4b-5195-ad99-5d412786f5c8","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"Embora seja, conforme disposto na CF, órgão do Poder Judiciário, o CNJ não exerce atividade judicante, não lhe sendo permitido reexaminar atos de conteúdo jurisdicional formalizados por magistrados ou tribunais.","official_answer":"C","explanation":"O controle do Conselho não é recurso universal para reformar o mérito de atos jurisdicionais. É necessário distinguir ato administrativo e atividade de julgar. Base conferida: Art. 103-B. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 103-B"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","documentTitle":"Poder judiciario composicao conselho nacional de justica","publisher":"AlfaCon","documentSha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","page":6,"itemNumber":3,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":175,"statement":"A revisão, de ofício ou por provocação, dos processos disciplinares, julgados há menos de um ano, de juízes e membros de tribunais é da competência do CNJ.","content_fingerprint":"a revisao de oficio ou por provocacao dos processos disciplinares julgados ha menos de um ano de juizes e membros de tribunais e da competencia do cnj","audit":{"id":"7988f148-0d74-5f70-8f02-f3e27c320273","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":6,"item_number":4,"extracted_statement":"A revisão, de ofício ou por provocação, dos processos disciplinares, julgados há menos de um ano, de juízes e membros de tribunais é da competência do CNJ.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"2ecd8926-a43b-51af-a496-92a37beeb9c6","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"2ecd8926-a43b-51af-a496-92a37beeb9c6","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504:4","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"A revisão, de ofício ou por provocação, dos processos disciplinares, julgados há menos de um ano, de juízes e membros de tribunais é da competência do CNJ.","official_answer":"C","explanation":"O inciso contempla revisão dos processos disciplinares julgados há menos de um ano, de ofício ou por provocação, nas condições constitucionais. Base conferida: Art. 103-B, § 4º, V. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 103-B, § 4º, V"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","documentTitle":"Poder judiciario composicao conselho nacional de justica","publisher":"AlfaCon","documentSha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","page":6,"itemNumber":4,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":176,"statement":"De acordo com STF, o Conselho Nacional de Justiça, que é órgão do Poder Judiciário, tem competência para apreciar a constitucionalidade de atos administrativos.","content_fingerprint":"de acordo com stf o conselho nacional de justica que e orgao do poder judiciario tem competencia para apreciar a constitucionalidade de atos administrativos","audit":{"id":"afd9177d-786d-5db0-8780-3c7ca84fa181","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":6,"item_number":5,"extracted_statement":"De acordo com STF, o Conselho Nacional de Justiça, que é órgão do Poder Judiciário, tem competência para apreciar a constitucionalidade de atos administrativos.","provided_answer":"ERRADO","current_answer":null,"review_status":"needs_review","review_note":"Exige jurisprudência atual sobre controle de legalidade/constitucionalidade de atos pelo CNJ.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":177,"statement":"O controle administrativo exercido pelo CNJ é subsidiário e pressupõe prévia atuação pelos tribunais ordinários.","content_fingerprint":"o controle administrativo exercido pelo cnj e subsidiario e pressupoe previa atuacao pelos tribunais ordinarios","audit":{"id":"f871d639-a00c-5df1-8d1b-d9a2ec6e1297","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":7,"item_number":6,"extracted_statement":"O controle administrativo exercido pelo CNJ é subsidiário e pressupõe prévia atuação pelos tribunais ordinários.","provided_answer":"ERRADO","current_answer":null,"review_status":"needs_review","review_note":"Exige precedente oficial atual sobre competência concorrente do CNJ.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":178,"statement":"A indicação dos membros do Conselho Nacional de Justiça, à exceção do presidente do Supremo Tribunal Federal, deve ser aprovada, por maioria simples, pelo Senado Federal, sendo esses membros nomeados pelo Presidente da República.","content_fingerprint":"a indicacao dos membros do conselho nacional de justica a excecao do presidente do supremo tribunal federal deve ser aprovada por maioria simples pelo senado federal sendo esses membros nomeados pelo presidente da republica","audit":{"id":"dc1e1257-2b87-5b5f-afe5-20662017a645","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":7,"item_number":7,"extracted_statement":"A indicação dos membros do Conselho Nacional de Justiça, à exceção do presidente do Supremo Tribunal Federal, deve ser aprovada, por maioria simples, pelo Senado Federal, sendo esses membros nomeados pelo Presidente da República.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"f1601683-ee6c-51d2-8a07-62209f8664cf","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"f1601683-ee6c-51d2-8a07-62209f8664cf","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504:7","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"A indicação dos membros do Conselho Nacional de Justiça, à exceção do presidente do Supremo Tribunal Federal, deve ser aprovada, por maioria simples, pelo Senado Federal, sendo esses membros nomeados pelo Presidente da República.","official_answer":"E","explanation":"A aprovação prevista é por maioria absoluta do Senado, com as regras de composição pertinentes. Não se deve trocá-la por maioria simples. Base conferida: Art. 103-B, § 2º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 103-B, § 2º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","documentTitle":"Poder judiciario composicao conselho nacional de justica","publisher":"AlfaCon","documentSha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","page":7,"itemNumber":7,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":179,"statement":"O CNJ exerce controle jurisdicional universal do mérito de todas as decisões judiciais, além do controle administrativo, financeiro e dos deveres funcionais.","content_fingerprint":"o cnj exerce controle jurisdicional universal do merito de todas as decisoes judiciais alem do controle administrativo financeiro e dos deveres funcionais","audit":{"id":"787c001c-0a0f-5304-b598-37ef86270218","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":7,"item_number":8,"extracted_statement":"Ao Conselho Nacional de Justiça cabe o controle da atuação jurídica, administrativa e financeira do Poder Judiciário e do cumprimento dos deveres funcionais dos juízes e servidores vinculados ao Poder Judiciário.","provided_answer":"ERRADO","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático. Redação delimitada/atualizada para evitar ambiguidade ou regra superada.","question_table":"curated_question_catalog","question_id":"e74bdd75-5854-5f6f-86eb-2c8f7d9ae722","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"e74bdd75-5854-5f6f-86eb-2c8f7d9ae722","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504:8","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"O CNJ exerce controle jurisdicional universal do mérito de todas as decisões judiciais, além do controle administrativo, financeiro e dos deveres funcionais.","official_answer":"E","explanation":"O item foi delimitado para distinguir controle administrativo, financeiro e disciplinar de revisão universal do mérito jurisdicional. O Conselho não é instância recursal comum de toda sentença. Base conferida: Art. 103-B, § 4º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 103-B, § 4º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","documentTitle":"Poder judiciario composicao conselho nacional de justica","publisher":"AlfaCon","documentSha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","page":7,"itemNumber":8,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":180,"statement":"O Conselho Nacional de Justiça não tem qualquer competência sobre o STF e seus ministros.","content_fingerprint":"o conselho nacional de justica nao tem qualquer competencia sobre o stf e seus ministros","audit":{"id":"ad7ab31c-682e-5590-8cd0-4913acc01705","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":7,"item_number":9,"extracted_statement":"O Conselho Nacional de Justiça não tem qualquer competência sobre o STF e seus ministros.","provided_answer":"CERTO","current_answer":null,"review_status":"needs_review","review_note":"Exige jurisprudência oficial sobre limites da atuação do CNJ em relação ao STF.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":181,"statement":"O Conselho Nacional de Justiça, a quem compete zelar pela autonomia do Poder Judiciário e pelo cumprimento do Estatuto da Magistratura, pode expedir atos regulamentares, no âmbito de sua competência, ou recomendar providências.","content_fingerprint":"o conselho nacional de justica a quem compete zelar pela autonomia do poder judiciario e pelo cumprimento do estatuto da magistratura pode expedir atos regulamentares no ambito de sua competencia ou recomendar providencias","audit":{"id":"72e3f405-7c22-5842-ae07-d41792e015a3","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":7,"item_number":10,"extracted_statement":"O Conselho Nacional de Justiça, a quem compete zelar pela autonomia do Poder Judiciário e pelo cumprimento do Estatuto da Magistratura, pode expedir atos regulamentares, no âmbito de sua competência, ou recomendar providências.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"bfa7965f-efab-50fb-a9e7-d90ad2fd3bc3","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"bfa7965f-efab-50fb-a9e7-d90ad2fd3bc3","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504:10","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"O Conselho Nacional de Justiça, a quem compete zelar pela autonomia do Poder Judiciário e pelo cumprimento do Estatuto da Magistratura, pode expedir atos regulamentares, no âmbito de sua competência, ou recomendar providências.","official_answer":"C","explanation":"O Conselho pode expedir atos regulamentares no âmbito de sua competência ou recomendar providências. A referência ao âmbito impede uma autorização normativa ilimitada. Base conferida: Art. 103-B, § 4º, I. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 103-B, § 4º, I"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","documentTitle":"Poder judiciario composicao conselho nacional de justica","publisher":"AlfaCon","documentSha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","page":7,"itemNumber":10,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":182,"statement":"A função de ministro-corregedor do Conselho Nacional de Justiça deve ser exercida por ministro do STJ.","content_fingerprint":"a funcao de ministro corregedor do conselho nacional de justica deve ser exercida por ministro do stj","audit":{"id":"c326e90b-55fd-5290-aeda-c3777b011541","document_sha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","document_name":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","source_page":7,"item_number":11,"extracted_statement":"A função de ministro-corregedor do Conselho Nacional de Justiça deve ser exercida por ministro do STJ.","provided_answer":"CERTO","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"c9f4f354-7853-55e4-97ae-4b86a28e8062","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"c9f4f354-7853-55e4-97ae-4b86a28e8062","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504:11","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"A função de ministro-corregedor do Conselho Nacional de Justiça deve ser exercida por ministro do STJ.","official_answer":"C","explanation":"A função de corregedor é exercida pelo ministro do STJ que integra o Conselho. Não cabe indistintamente a qualquer membro. Base conferida: Art. 103-B, § 5º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 103-B, § 5º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-03_AlfaCon--poder-judiciario-composicao-conselho-nacional-de-justica.pdf","documentTitle":"Poder judiciario composicao conselho nacional de justica","publisher":"AlfaCon","documentSha256":"e7df57f31eeb13abd6b0c516efc2d03c782a135f5ea1645c665489bf8684a504","page":7,"itemNumber":11,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":183,"statement":"Os ministros do Supremo Tribunal Federal (STF) são nomeados pelo Presidente da República após aprovação do Congresso Nacional.","content_fingerprint":"os ministros do supremo tribunal federal stf sao nomeados pelo presidente da republica apos aprovacao do congresso nacional","audit":{"id":"ce55963c-fc6b-5cef-8da0-07ff7f9d91f1","document_sha256":"41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388","document_name":"08-04_AlfaCon--poder-judiciario-competencias.pdf","source_page":8,"item_number":1,"extracted_statement":"Os ministros do Supremo Tribunal Federal (STF) são nomeados pelo Presidente da República após aprovação do Congresso Nacional.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"490e68cc-ceb0-5076-bef4-fc3c21f56de5","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"490e68cc-ceb0-5076-bef4-fc3c21f56de5","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"Os ministros do Supremo Tribunal Federal (STF) são nomeados pelo Presidente da República após aprovação do Congresso Nacional.","official_answer":"E","explanation":"A escolha exige aprovação pela maioria absoluta do Senado Federal, não do Congresso como órgão conjunto. Base conferida: Art. 101, parágrafo único. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 101, parágrafo único"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-04_AlfaCon--poder-judiciario-competencias.pdf","documentTitle":"Poder judiciario competencias","publisher":"AlfaCon","documentSha256":"41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388","page":8,"itemNumber":1,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":184,"statement":"Mandado de segurança impetrado contra ato de ministro de Estado consistente no lançamento de edital para concurso público com notório conteúdo discriminatório deverá ser julgado pelo Supremo Tribunal Federal.","content_fingerprint":"mandado de seguranca impetrado contra ato de ministro de estado consistente no lancamento de edital para concurso publico com notorio conteudo discriminatorio devera ser julgado pelo supremo tribunal federal","audit":{"id":"b3ea6070-5ba8-5094-a6bb-41d1575a2ed2","document_sha256":"41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388","document_name":"08-04_AlfaCon--poder-judiciario-competencias.pdf","source_page":8,"item_number":2,"extracted_statement":"Mandado de segurança impetrado contra ato de ministro de Estado consistente no lançamento de edital para concurso público com notório conteúdo discriminatório deverá ser julgado pelo Supremo Tribunal Federal.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"bca304e8-5afc-59e9-b965-c7ddf7a3b654","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"bca304e8-5afc-59e9-b965-c7ddf7a3b654","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388:2","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"Mandado de segurança impetrado contra ato de ministro de Estado consistente no lançamento de edital para concurso público com notório conteúdo discriminatório deverá ser julgado pelo Supremo Tribunal Federal.","official_answer":"E","explanation":"A competência originária indicada para mandado de segurança contra ministro de Estado é do STJ, nas condições constitucionais, não do STF pelo simples título da autoridade. Base conferida: Art. 105, I, b. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 105, I, b"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-04_AlfaCon--poder-judiciario-competencias.pdf","documentTitle":"Poder judiciario competencias","publisher":"AlfaCon","documentSha256":"41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388","page":8,"itemNumber":2,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":185,"statement":"Compete ao Supremo Tribunal Federal, processar e julgar, originariamente o crime político.","content_fingerprint":"compete ao supremo tribunal federal processar e julgar originariamente o crime politico","audit":{"id":"42f9d37f-7993-5b71-aec1-3b72dbfe3a22","document_sha256":"41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388","document_name":"08-04_AlfaCon--poder-judiciario-competencias.pdf","source_page":8,"item_number":3,"extracted_statement":"Compete ao Supremo Tribunal Federal, processar e julgar, originariamente o crime político.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"5af0673f-3a3e-5235-a063-4c9e5dd1a0f0","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"5af0673f-3a3e-5235-a063-4c9e5dd1a0f0","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"Compete ao Supremo Tribunal Federal, processar e julgar, originariamente o crime político.","official_answer":"E","explanation":"Crime político tem tratamento de competência e recurso próprio. O STF possui hipótese de recurso ordinário; isso não o torna julgador originário genérico. Base conferida: Art. 102, II, b; Art. 109, IV. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 102, II, b; Art. 109, IV"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-04_AlfaCon--poder-judiciario-competencias.pdf","documentTitle":"Poder judiciario competencias","publisher":"AlfaCon","documentSha256":"41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388","page":8,"itemNumber":3,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":186,"statement":"Compete ao Supremo Tribunal Federal processar e julgar originariamente o litígio entre Estado estrangeiro ou organismo internacional e a União, o Estado, o Distrito Federal ou o Território.","content_fingerprint":"compete ao supremo tribunal federal processar e julgar originariamente o litigio entre estado estrangeiro ou organismo internacional e a uniao o estado o distrito federal ou o territorio","audit":{"id":"0275e205-7bad-5dda-ab0f-f1aa5730df1a","document_sha256":"41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388","document_name":"08-04_AlfaCon--poder-judiciario-competencias.pdf","source_page":8,"item_number":4,"extracted_statement":"Compete ao Supremo Tribunal Federal processar e julgar originariamente o litígio entre Estado estrangeiro ou organismo internacional e a União, o Estado, o Distrito Federal ou o Território.","provided_answer":"C","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"6ea07f9b-1356-5dae-9a8b-ec7da1b5e80f","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"6ea07f9b-1356-5dae-9a8b-ec7da1b5e80f","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388:4","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"Compete ao Supremo Tribunal Federal processar e julgar originariamente o litígio entre Estado estrangeiro ou organismo internacional e a União, o Estado, o Distrito Federal ou o Território.","official_answer":"C","explanation":"O litígio descrito corresponde ao recorte originário do STF. É necessário preservar as partes indicadas, sem estender a resposta indistintamente a todo conflito internacional. Base conferida: Art. 102, I, e. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 102, I, e"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-04_AlfaCon--poder-judiciario-competencias.pdf","documentTitle":"Poder judiciario competencias","publisher":"AlfaCon","documentSha256":"41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388","page":8,"itemNumber":4,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":187,"statement":"Os membros do Congresso Nacional e os governadores dos estados, quando cometem infrações penais comuns, são processados e julgados, originariamente, pelo Supremo Tribunal Federal.","content_fingerprint":"os membros do congresso nacional e os governadores dos estados quando cometem infracoes penais comuns sao processados e julgados originariamente pelo supremo tribunal federal","audit":{"id":"f3aa1498-6a69-59ce-8a1e-deb81b8581e5","document_sha256":"41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388","document_name":"08-04_AlfaCon--poder-judiciario-competencias.pdf","source_page":8,"item_number":5,"extracted_statement":"Os membros do Congresso Nacional e os governadores dos estados, quando cometem infrações penais comuns, são processados e julgados, originariamente, pelo Supremo Tribunal Federal.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"d5ccc146-5815-583d-a4ab-44748c0aaa32","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"d5ccc146-5815-583d-a4ab-44748c0aaa32","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388:5","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Tribunais: composição e competências","tested_topic":"Tribunais: composição e competências","question_text":"Os membros do Congresso Nacional e os governadores dos estados, quando cometem infrações penais comuns, são processados e julgados, originariamente, pelo Supremo Tribunal Federal.","official_answer":"E","explanation":"Governadores possuem disciplina no STJ para a hipótese constitucional pertinente. Não se pode reunir todas as autoridades indicadas sob competência penal originária do STF. Base conferida: Art. 102, I, b; Art. 105, I, a. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 102, I, b; Art. 105, I, a"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-04_AlfaCon--poder-judiciario-competencias.pdf","documentTitle":"Poder judiciario competencias","publisher":"AlfaCon","documentSha256":"41afe3d355bf487ebf518c0c8b9186dc24db1070ee87218705b6c89ffddfe388","page":8,"itemNumber":5,"materialSlug":"constitucional-tribunais-competencias-cnj","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":188,"statement":"Com referência aos princípios e às garantias do Ministério Público (MP), assinale a opção correta.\n(A) Dado o princípio da unidade, os membros do MP podem ser substituídos uns pelos outros, desde que sejam da mesma carreira.\n(B) Nos limites da ordem jurídica, a independência funcional protege a formação da convicção jurídica pelo membro do Ministério Público no exercício de suas atribuições.\n(C) Em razão da inamovibilidade, assegura-se aos membros do MP que não sejam removidos em nenhuma hipótese.\n(D) Dada a vitaliciedade, os membros do MP não podem ser destituídos do cargo, ainda que alcancem a idade para a aposentadoria compulsória.\n(E) Em decorrência do princípio da indivisibilidade, os promotores e os procuradores integram um só órgão, sob a direção de um só chefe.","content_fingerprint":"com referencia aos principios e as garantias do ministerio publico mp assinale a opcao correta a dado o principio da unidade os membros do mp podem ser substituidos uns pelos outros desde que sejam da mesma carreira b nos limites da ordem juridica a independencia funcional protege a formacao da conviccao juridica pelo membro do ministerio publico no exercicio de suas atribuicoes c em razao da inamovibilidade assegura se aos membros do mp que nao sejam removidos em nenhuma hipotese d dada a vitaliciedade os membros do mp nao podem ser destituidos do cargo ainda que alcancem a idade para a aposentadoria compulsoria e em decorrencia do principio da indivisibilidade os promotores e os procuradores integram um so orgao sob a direcao de um so chefe","audit":{"id":"5462f019-7edb-5bf5-9cc1-16426b6fb348","document_sha256":"c8113eee610392f1dfdd902bab2abf5ab52330e8dca7a12c03937b0e6bd421c1","document_name":"08-05_AlfaCon--funcoes-essenciais-a-justica.pdf","source_page":8,"item_number":1,"extracted_statement":"Com referência aos princípios e às garantias do Ministério Público (MP), assinale a opção correta. a) Dado o princípio da unidade, os membros do MP podem ser substituídos uns pelos outros, desde que sejam da mesma carreira. b) Em decorrência do princípio da independência funcional, cada um dos membros do MP vincula-se somente à sua convicção jurídica, quando se trata de assunto relacionado com sua atividade funcional. c) Em razão da inamovibilidade, assegura-se aos membros do MP que não sejam removidos em nenhuma hipótese. d) Dada a vitaliciedade, os membros do MP não podem ser destituídos do cargo, ainda que alcancem a idade para a aposentadoria compulsória. e) Em decorrência do princípio da indivisibilidade, os promotores e os procuradores integram um só órgão, sob a direção de um só chefe.","provided_answer":"B","current_answer":"B","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático. Redação delimitada/atualizada para evitar ambiguidade ou regra superada.","question_table":"curated_question_catalog","question_id":"9ea3c937-f666-543c-b056-f0008a654d25","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"9ea3c937-f666-543c-b056-f0008a654d25","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:c8113eee610392f1dfdd902bab2abf5ab52330e8dca7a12c03937b0e6bd421c1:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Funções essenciais à Justiça","tested_topic":"Funções essenciais à Justiça","question_text":"Com referência aos princípios e às garantias do Ministério Público (MP), assinale a opção correta.\n(A) Dado o princípio da unidade, os membros do MP podem ser substituídos uns pelos outros, desde que sejam da mesma carreira.\n(B) Nos limites da ordem jurídica, a independência funcional protege a formação da convicção jurídica pelo membro do Ministério Público no exercício de suas atribuições.\n(C) Em razão da inamovibilidade, assegura-se aos membros do MP que não sejam removidos em nenhuma hipótese.\n(D) Dada a vitaliciedade, os membros do MP não podem ser destituídos do cargo, ainda que alcancem a idade para a aposentadoria compulsória.\n(E) Em decorrência do princípio da indivisibilidade, os promotores e os procuradores integram um só órgão, sob a direção de um só chefe.","official_answer":"B","explanation":"A alternativa B corresponde à independência funcional, entendida dentro da ordem jurídica, e não como licença para arbitrariedade. A alternativa A descreve indivisibilidade com nome de unidade; E faz a troca inversa; C e D tratam garantias como absolutas e ignoram exceções e limites constitucionais. Base conferida: Art. 127, § 1º; Art. 128, § 5º. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 127, § 1º; Art. 128, § 5º"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"08-05_AlfaCon--funcoes-essenciais-a-justica.pdf","documentTitle":"Funcoes essenciais a justica","publisher":"AlfaCon","documentSha256":"c8113eee610392f1dfdd902bab2abf5ab52330e8dca7a12c03937b0e6bd421c1","page":8,"itemNumber":1,"materialSlug":"constitucional-funcoes-essenciais-justica","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":189,"statement":"A República Federativa do Brasil, formada pela união indissolúvel dos estados, municípios e Distrito Federal, adota a federação como forma de Estado.","content_fingerprint":"a republica federativa do brasil formada pela uniao indissoluvel dos estados municipios e distrito federal adota a federacao como forma de estado","audit":{"id":"e41f2a61-ec94-5b48-a937-a3cb6179cd03","document_sha256":"5be3631357032a9261538c3a2b1f7d3f675101eefc4005680056a571430edf43","document_name":"01-01_AlfaCon--principios-fundamentais-parte-1.pdf","source_page":4,"item_number":1,"extracted_statement":"A República Federativa do Brasil, formada pela união indissolúvel dos estados, municípios e Distrito Federal, adota a federação como forma de Estado.","provided_answer":"C","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"e1ddd386-7830-5501-9c2a-202657b49825","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"e1ddd386-7830-5501-9c2a-202657b49825","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:5be3631357032a9261538c3a2b1f7d3f675101eefc4005680056a571430edf43:1","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Princípios fundamentais","tested_topic":"Princípios fundamentais","question_text":"A República Federativa do Brasil, formada pela união indissolúvel dos estados, municípios e Distrito Federal, adota a federação como forma de Estado.","official_answer":"C","explanation":"A forma de Estado brasileira é a Federação e o vínculo é indissolúvel. A autonomia dos entes deve ser lida nos limites constitucionais. Base conferida: Arts. 1º e 18. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Arts. 1º e 18"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"01-01_AlfaCon--principios-fundamentais-parte-1.pdf","documentTitle":"Principios fundamentais parte 1","publisher":"AlfaCon","documentSha256":"5be3631357032a9261538c3a2b1f7d3f675101eefc4005680056a571430edf43","page":4,"itemNumber":1,"materialSlug":"constitucional-principios-fundamentais-federacao-republica","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":190,"statement":"A igualdade perante a lei, a periodicidade dos mandatos políticos e a responsabilidade dos mandatários são características do princípio republicano.","content_fingerprint":"a igualdade perante a lei a periodicidade dos mandatos politicos e a responsabilidade dos mandatarios sao caracteristicas do principio republicano","audit":{"id":"8fa58b26-3c44-5a36-86ba-1630dbfbda33","document_sha256":"5be3631357032a9261538c3a2b1f7d3f675101eefc4005680056a571430edf43","document_name":"01-01_AlfaCon--principios-fundamentais-parte-1.pdf","source_page":4,"item_number":2,"extracted_statement":"A igualdade perante a lei, a periodicidade dos mandatos políticos e a responsabilidade dos mandatários são características do princípio republicano.","provided_answer":"C","current_answer":"C","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"853076f3-2a1e-51d2-a619-901d4e6c2acc","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"853076f3-2a1e-51d2-a619-901d4e6c2acc","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:5be3631357032a9261538c3a2b1f7d3f675101eefc4005680056a571430edf43:2","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Princípios fundamentais","tested_topic":"Princípios fundamentais","question_text":"A igualdade perante a lei, a periodicidade dos mandatos políticos e a responsabilidade dos mandatários são características do princípio republicano.","official_answer":"C","explanation":"Igualdade, periodicidade dos mandatos políticos e responsabilização ajudam a caracterizar a República. Não se deve concluir que todo cargo público seja eletivo. Base conferida: Art. 5º, caput; Art. 14; Art. 85. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Art. 5º, caput; Art. 14; Art. 85"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"01-01_AlfaCon--principios-fundamentais-parte-1.pdf","documentTitle":"Principios fundamentais parte 1","publisher":"AlfaCon","documentSha256":"5be3631357032a9261538c3a2b1f7d3f675101eefc4005680056a571430edf43","page":4,"itemNumber":2,"materialSlug":"constitucional-principios-fundamentais-federacao-republica","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}},{"input_index":191,"statement":"A forma de Estado adotada pela Constituição é a Federação, que se embasa na descentralização política, isto é, na soberania dos estados-membros, que possuem capacidade de se auto-organizarem por meio das próprias constituições.","content_fingerprint":"a forma de estado adotada pela constituicao e a federacao que se embasa na descentralizacao politica isto e na soberania dos estados membros que possuem capacidade de se auto organizarem por meio das proprias constituicoes","audit":{"id":"2552c0c3-0acf-55b8-88ca-0125cdc66f68","document_sha256":"5be3631357032a9261538c3a2b1f7d3f675101eefc4005680056a571430edf43","document_name":"01-01_AlfaCon--principios-fundamentais-parte-1.pdf","source_page":null,"item_number":3,"extracted_statement":"A forma de Estado adotada pela Constituição é a Federação, que se embasa na descentralização política, isto é, na soberania dos estados-membros, que possuem capacidade de se auto-organizarem por meio das próprias constituições.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Enunciado, gabarito e comentário conferidos no recorte indicado; catalogado como material didático.","question_table":"curated_question_catalog","question_id":"68c144b9-4002-5eaf-a918-caa40d9f813f","reviewed_at":"2026-10-24T22:00:40.123042+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"68c144b9-4002-5eaf-a918-caa40d9f813f","source_id":"31420f66-9c12-4787-bdc0-f55f77525880","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","external_item_key":"didactic:5be3631357032a9261538c3a2b1f7d3f675101eefc4005680056a571430edf43:3","contest_name":"Material didático — Direito Constitucional","contest_year":2026,"career_name":"Delegado de Polícia Civil","exam_board":"Material didático","subject":"Direito Constitucional","subtopic":"Princípios fundamentais","tested_topic":"Princípios fundamentais","question_text":"A forma de Estado adotada pela Constituição é a Federação, que se embasa na descentralização política, isto é, na soberania dos estados-membros, que possuem capacidade de se auto-organizarem por meio das próprias constituições.","official_answer":"E","explanation":"O erro é atribuir soberania aos estados-membros. Eles têm autonomia para se organizar dentro da Constituição, sem direito unilateral de secessão. Base conferida: Arts. 1º e 18. Origem: exercício de material didático, adaptado e revisado; sem atribuição a banca oficial.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","artigo":"Arts. 1º e 18"}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-24T22:00:40.123042+00:00","law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"01-01_AlfaCon--principios-fundamentais-parte-1.pdf","documentTitle":"Principios fundamentais parte 1","publisher":"AlfaCon","documentSha256":"5be3631357032a9261538c3a2b1f7d3f675101eefc4005680056a571430edf43","page":null,"itemNumber":3,"materialSlug":"constitucional-principios-fundamentais-federacao-republica","reviewedAt":"2026-10-24T22:00:40.123042+00:00","adapted":true}}}],"semantic_scope":"Deduplicação exata normalizada, considerando suporte/opções/figuras. Não certifica equivalência semântica de todos os itens do acervo."}$didactic_1d23a6e242e5c256$::jsonb);
create function pg_temp.didactic_norm(v text) returns text language sql immutable as $$
 select btrim(regexp_replace(translate(lower(regexp_replace(coalesce(v,''),'([[:alnum:]])-[[:space:]]+([[:alnum:]])','\1\2','g')),
 'áàâãäåéèêëíìîïóòôõöúùûüçñ','aaaaaaeeeeiiiiooooouuuucn'),'[^a-z0-9]+',' ','g'))
$$;
create temp table didactic_existing on commit drop as
 select pg_temp.didactic_norm(q.question_text) as fingerprint from public.curated_question_catalog q where q.subject='Direito Constitucional'
 union all select pg_temp.didactic_norm(q.stem) from public.board_exam_questions q where q.subject='Direito Constitucional' and coalesce(q.support_text,'')='' and coalesce(q.options,'{}'::jsonb) in ('{}'::jsonb,'[]'::jsonb) and coalesce(to_jsonb(q.figure_urls),'[]'::jsonb)='[]'::jsonb
 union all select pg_temp.didactic_norm(q.question_text) from public.official_exam_questions q where q.subject='Direito Constitucional' and q.support_text_id is null;
create index on didactic_existing using hash(fingerprint);
do $guard$
declare p jsonb;r jsonb;existing public.curated_question_catalog;old public.didactic_question_imports;has_existing boolean;
begin
 select payload into p from didactic_payload;
 if not exists(select 1 from public.user_roles where user_id=(p->>'actor')::uuid and role::text='admin') then raise exception 'Responsável de publicação não é administrador.'; end if;
 if not exists(select 1 from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where t.id=(p#>>'{topic,id}')::uuid and t.content_status='current' and e.status='active' and t.topic_text=p#>>'{topic,topic_text}') then raise exception 'Tópico de edital não está atual.'; end if;
 if exists(select 1 from jsonb_array_elements(p->'sources') s left join public.content_sources c on c.id=(s->>'id')::uuid where c.id is null or not c.is_official or c.status<>'vigente' or c.url<>s->>'url') then raise exception 'Fonte oficial deixou de estar verificada.'; end if;
 for r in select value from jsonb_array_elements(p->'rows') loop
  select * into old from public.didactic_question_imports where document_sha256=r#>>'{audit,document_sha256}' and item_number=(r#>>'{audit,item_number}')::integer for update;
  if found and (not(to_jsonb(old) @> ((r->'audit')-'reviewed_at')) or old.reviewed_at is distinct from (r#>>'{audit,reviewed_at}')::timestamptz) then raise exception 'Importação anterior diferente; revisar sem sobrescrever.'; end if;
  if r->'question'<>'null'::jsonb then
   if r#>>'{audit,review_status}'<>'published' or r#>>'{question,didactic_provenance,origin}'<>'didactic_material' or r#>>'{question,content_status}'<>'active' or r#>>'{question,exam_board}'<>'Material didático' then raise exception 'Classificação inválida.'; end if;
   if not exists(select 1 from public.study_materials m where m.slug=r#>>'{question,didactic_provenance,materialSlug}' and m.content_status='active') then raise exception 'Material de apoio indisponível.'; end if;
   select * into existing from public.curated_question_catalog where id=(r#>>'{question,id}')::uuid for update;
   has_existing=found;
   if has_existing and (not(to_jsonb(existing) @> ((r->'question')-'verified_at'-'law_version_checked_at')) or existing.verified_at<>(r#>>'{question,verified_at}')::timestamptz or existing.law_version_checked_at<>(r#>>'{question,law_version_checked_at}')::timestamptz) then raise exception 'Questão existente diferente.'; end if;
   if not has_existing and exists(select 1 from didactic_existing where fingerprint=r->>'content_fingerprint') then raise exception 'Conteúdo equivalente cadastrado em concorrência; reutilizar em vez de duplicar.'; end if;
  elsif r#>>'{audit,review_status}'='needs_review' and (r#>>'{audit,current_answer}' is not null or r#>>'{audit,question_id}' is not null) then raise exception 'Item pendente não pode ser liberado para treino.';
  end if;
 end loop;
end $guard$;
insert into public.curated_question_catalog(id,source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,tested_topic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,verified_at,law_version_checked_at,didactic_provenance)
select q.id,q.source_id,q.syllabus_topic_id,q.external_item_key,q.contest_name,q.contest_year,q.career_name,q.exam_board,q.subject,q.subtopic,q.tested_topic,q.question_text,q.official_answer,q.explanation,q.legal_basis,q.difficulty,q.content_status,q.is_original,q.verified_at,q.law_version_checked_at,q.didactic_provenance from didactic_payload p cross join lateral jsonb_array_elements(p.payload->'rows') r cross join lateral jsonb_populate_record(null::public.curated_question_catalog,r->'question') q where r->'question'<>'null'::jsonb on conflict(source_id,external_item_key) do nothing;
insert into public.didactic_question_imports(id,document_sha256,document_name,source_page,item_number,extracted_statement,provided_answer,current_answer,review_status,review_note,question_table,question_id,reviewed_at,reviewed_by)
select d.id,d.document_sha256,d.document_name,d.source_page,d.item_number,d.extracted_statement,d.provided_answer,d.current_answer,d.review_status,d.review_note,d.question_table,d.question_id,d.reviewed_at,d.reviewed_by from didactic_payload p cross join lateral jsonb_array_elements(p.payload->'rows') r cross join lateral jsonb_populate_record(null::public.didactic_question_imports,r->'audit') d on conflict(document_sha256,item_number) do nothing;
do $verify$
declare p jsonb;r jsonb;matched boolean;
begin
 select payload into p from didactic_payload;
 for r in select value from jsonb_array_elements(p->'rows') loop
  if not exists(select 1 from public.didactic_question_imports d where d.id=(r#>>'{audit,id}')::uuid and d.review_status=r#>>'{audit,review_status}' and d.extracted_statement=r#>>'{audit,extracted_statement}') then raise exception 'Falha na conferência da classificação.'; end if;
  if r#>>'{audit,review_status}' in ('published','duplicate_reused') then
   if r#>>'{audit,question_table}'='curated_question_catalog' then select exists(select 1 from public.curated_question_catalog q where q.id=(r#>>'{audit,question_id}')::uuid and q.content_status='active' and q.official_answer=r#>>'{audit,current_answer}') into matched;
   elsif r#>>'{audit,question_table}'='board_exam_questions' then select exists(select 1 from public.board_exam_questions q where q.id=(r#>>'{audit,question_id}')::uuid and q.content_status='active' and q.official_answer=r#>>'{audit,current_answer}') into matched;
   else select exists(select 1 from public.official_exam_questions q where q.id=(r#>>'{audit,question_id}')::uuid and q.content_status='active' and q.official_answer=r#>>'{audit,current_answer}') into matched; end if;
   if not matched then raise exception 'Questão de treino não encontrada ou gabarito divergente.'; end if;
  end if;
  if r->'question'<>'null'::jsonb and not exists(select 1 from public.curated_question_catalog q where q.id=(r#>>'{question,id}')::uuid and q.question_text=r#>>'{question,question_text}' and q.explanation=r#>>'{question,explanation}' and q.didactic_provenance=r#>'{question,didactic_provenance}' and q.legal_basis=r#>'{question,legal_basis}') then raise exception 'Falha na leitura final da questão.'; end if;
 end loop;
end $verify$;
select d.review_status,count(*) as count from public.didactic_question_imports d join didactic_payload p on true
where d.id in(select (r#>>'{audit,id}')::uuid from jsonb_array_elements(p.payload->'rows') r) group by d.review_status order by d.review_status;
commit;
